HSKDATA("examples/1",{"爱":[["苹果啊、香蕉啊，他都爱吃。","Píngguǒ a, xiāngjiāo a, tā dōu ài chī.","Apples, bananas — he likes them all.","G233"],["除工作外，他还爱读书。","Chú gōngzuò wài, tā hái ài dúshū.","Besides work, he also loves reading.","G376"]],"八":[["我明天早上八点在楼下等你。","Wǒ míngtiān zǎoshang bā diǎn zài lóu xià děng nǐ.","I will wait for you downstairs at eight tomorrow morning.","G320"],["今天是五月八号。","Jīntiān shì wǔ yuè bā hào.","Today is 8 May.","G44"],["我们八点半上课。","Wǒmen bā diǎn bàn shàngkè.","Our class starts at 8:30.","G44"]],"吧":[["既然你不舒服，就早点儿休息吧。","Jìrán nǐ bù shūfu, jiù zǎo diǎn ér xiūxi ba.","Since you are unwell, get some rest.","G266"],["既然你来了，就一起吃饭吧。","Jìrán nǐ lái le, jiù yīqǐ chīfàn ba.","Since you are here, eat with us.","G231"],["车放着也是放着，你开走吧。","Chē fàng zhe yě shì fàng zhe, nǐ kāi zǒu ba.","The car is just sitting there — take it.","G350"]],"白":[["反正有票，不看白不看。","Fǎnzhèng yǒu piào, bù kàn bái bù kàn.","We have tickets anyway, so we may as well watch.","G278"],["免费的，不拿白不拿。","Miǎnfèi de, bù ná bái bù ná.","It is free — you may as well take it.","G278"]],"百":[["这个城市有三百万人。","Zhè gè chéngshì yǒu sān bǎi wàn rén.","This city has three million people.","G57"],["价格上涨了百分之十。","Jiàgé shàngzhǎng le bǎi fēn zhī shí.","The price rose by ten per cent.","G273"],["往前走五百米。","Wǎng qián zǒu wǔ bǎi mǐ.","Walk 500 metres straight ahead.","G70"]],"班":[["我们班的同学都来了。","Wǒmen bān de tóngxué dōu lái le.","All the students in our class came.","G162"]],"半":[["我们八点半上课。","Wǒmen bā diǎn bàn shàngkè.","Our class starts at 8:30.","G44"],["现在是三点半。","Xiànzài shì sān diǎn bàn.","It's half past three.","G7"]],"半天":[["我看了半天没看懂。","Wǒ kàn le bàntiān méi kàn dǒng.","I looked for ages without understanding.","G328"]],"帮":[["闲着也是闲着，帮个忙吧。","Xián zhe yě shì xián zhe, bāng gè máng ba.","You are free anyway — lend a hand.","G350"],["他昨天帮了我的忙。","Tā zuótiān bāng le wǒ de máng.","He helped me yesterday.","G135"],["我愿意帮你。","Wǒ yuànyì bāng nǐ.","I am willing to help you.","G51"]],"帮忙":[["还朋友呢，一点儿都不帮忙。","Hái péngyou ne, yīdiǎnr dōu bù bāngmáng.","Some friend — no help at all.","G284"]],"包子":[["我吃了两个包子。","Wǒ chī le liǎng gè bāozi.","I ate two buns.","G21"]],"杯":[["他喝了一大杯水。","Tā hē le yī dà bēi shuǐ.","He drank a large glass of water.","G382"],["我要一杯咖啡。","Wǒ yào yī bēi kāfēi.","I want a cup of coffee.","G8"]],"杯子":[["他把杯子放在桌子上。","Tā bǎ bēizi fàng zài zhuōzi shàng.","He put the cup on the table.","G184"],["杯子被他给打碎了。","Bēizi bèi tā gěi dǎ suì le.","The cup got smashed by him.","G399"]],"北京":[["自从来到北京，我认识了很多朋友。","Zìcóng láidào Běijīng, wǒ rènshi le hěn duō péngyou.","Since coming to Beijing I have made many friends.","G151"],["你是去北京，还是去上海？","Nǐ shì qù Běijīng, háishi qù shàng hǎi?","Are you going to Beijing or Shanghai?","G112"],["我是在北京学的汉语。","Wǒ shì zài Běijīng xué de Hànyǔ.","It was in Beijing that I learned Chinese.","G123"]],"本":[["本想早点到，不料路上堵车。","Běn xiǎng zǎo diǎn dào, bùliào lùshang dǔchē.","I meant to arrive early, but there was traffic.","G379"],["本次会议共有二十人参加。","Běn cì huìyì gòngyǒu èr shí rén cānjiā.","Twenty people attended this meeting in total.","G217"],["这是一本关于历史的书。","Zhè shì yī běn guānyú lìshǐ de shū.","This is a book about history.","G226"]],"比":[["一般来说，南方比北方暖和。","Yībānláishuō, nánfāng bǐ běifāng nuǎnhuo.","Generally speaking, the south is warmer than the north.","G239"],["在他看来，努力比天赋重要。","Zài tā kànlái, nǔlì bǐ tiānfù zhòngyào.","In his view effort matters more than talent.","G318"],["这条路比那条近两公里。","Zhè tiáo lù bǐ nà tiáo jìn liǎng gōnglǐ.","This road is two kilometres shorter than that one.","G330"]],"别":[["外面下雨，还是别去了吧。","Wàimiàn xià yǔ, háishi bié qù le ba.","It's raining — better not go.","G93"],["你去就是了，别想那么多。","Nǐ qù jiùshì le, bié xiǎng nàme duō.","Just go — do not overthink it.","G283"],["既然决定了，就别后悔。","Jìrán juédìng le, jiù bié hòuhuǐ.","Since it is decided, no regrets.","G266"]],"病":[["因为他病了，所以虽然想来，也没能来。","Yīnwèi tā bìng le, suǒyǐ suīrán xiǎng lái, yě méi néng lái.","Because he was ill, although he wanted to come, he could not.","G343"],["他因病请假。","Tā yīn bìng qǐngjià.","He took leave because of illness.","G375"]],"不大":[["这件衣服不大不小，正合适。","Zhè jiàn yīfu bù dà bù xiǎo, zhèng héshì.","This garment is neither too big nor too small — just right.","G164"],["从目前情况来看，问题不大。","Cóng mùqián qíngkuàng lái kàn, wèntí bù dà.","Judging from the current situation, it is not a big problem.","G313"]],"不对":[["这样做是不对的。","Zhèyàng zuò shì bùduì de.","Doing it this way is wrong.","G253"]],"不用":[["你忙你的吧，不用管我。","Nǐ máng nǐ de ba, bùyòng guǎn wǒ.","Get on with your work, never mind me.","G285"],["你不用等我。","Nǐ bùyòng děng wǒ.","You don't have to wait for me.","G212"]],"不":[["如果下雨，我们就不去，而是在家看书。","Rúguǒ xià yǔ, wǒmen jiù bù qù, ér shì zàijiā kàn shū.","If it rains we will stay home and read instead.","G343"],["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["这不是钱的问题，而是原则问题。","Zhè bù shì qián de wèntí, ér shì yuánzé wèntí.","This is not about money but about principle.","G254"]],"菜":[["他不仅会做饭，还会做菜谱。","Tā bùjǐn huì zuòfàn, hái huì zuò cài pǔ.","He can not only cook but even write recipes.","G196"],["这里的菜好吃，而且不贵。","Zhèlǐ de cài hǎochī, érqiě bù guì.","The food here is tasty, and cheap too.","G111"],["菜很好吃，不过有点儿贵。","Cài hěn hǎochī, bùguò yǒudiǎnr guì.","The food is tasty, though a bit pricey.","G113"]],"茶":[["你喝茶还是喝咖啡？","Nǐ hē chá háishi hē kāfēi?","Will you have tea or coffee?","G19"],["我想喝茶或者咖啡。","Wǒ xiǎng hē chá huòzhě kāfēi.","I would like tea or coffee.","G77"],["你要茶还是咖啡？","Nǐ yào chá háishi kāfēi?","Do you want tea or coffee?","G33"]],"常常":[["他常常去图书馆。","Tā chángcháng qù túshūguǎn.","He often goes to the library.","G12"]],"唱":[["大家唱的唱，跳的跳。","Dàjiā chàng de chàng, tiào de tiào.","Some were singing, others dancing.","G317"]],"唱歌":[["他又会唱歌又会跳舞。","Tā yòu huì chànggē yòu huì tiàowǔ.","He can both sing and dance.","G94"],["她唱歌唱得很好听。","Tā chànggē chàng dé hěn hǎotīng.","She sings beautifully.","G99"]],"车":[["或是坐车，或是走路，都行。","Huòshì zuò chē, huòshì zǒulù, dōu xíng.","By bus or on foot — either is fine.","G331"],["车放着也是放着，你开走吧。","Chē fàng zhe yě shì fàng zhe, nǐ kāi zǒu ba.","The car is just sitting there — take it.","G350"],["我们坐车还是走路？","Wǒmen zuò chē háishi zǒulù?","Shall we take a bus or walk?","G112"]],"吃":[["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["苹果啊、香蕉啊，他都爱吃。","Píngguǒ a, xiāngjiāo a, tā dōu ài chī.","Apples, bananas — he likes them all.","G233"],["为了健康，你应该少吃盐。","Wèile jiànkāng, nǐ yīnggāi shǎo chī yán.","For your health you should eat less salt.","G156"]],"吃饭":[["既然你来了，就一起吃饭吧。","Jìrán nǐ lái le, jiù yīqǐ chīfàn ba.","Since you are here, eat with us.","G231"],["他一边吃饭，一边看电视。","Tā yībiān chīfàn, yībiān kàn diànshì.","He eats while watching TV.","G39"],["他很忙，甚至没时间吃饭。","Tā hěn máng, shènzhì méi shíjiān chīfàn.","He is so busy he has no time even to eat.","G258"]],"出":[["真有他的，居然想出这个办法。","Zhēn yǒu tā de, jūrán xiǎng chū zhè gè bànfǎ.","Trust him to come up with that.","G354"]],"出来":[["再难的题他也能做出来。","Zài nán de tí tā yě néng zuò chūlái.","He can solve even the hardest problem.","G342"],["他从房间里走出来了。","Tā cóng fángjiān lǐ zǒu chūlái le.","He walked out of the room.","G177"],["请把书拿出来。","Qǐng bǎ shū náchū lái.","Please take the book out.","G98"]],"出去":[["我想出去，偏偏下起雨来。","Wǒ xiǎng chūqù, piānpiān xià qǐ yǔ lái.","I wanted to go out and of course it started raining.","G370"],["孩子偷偷跑出去了。","Háizi tōutōu pǎo chūqù le.","The child slipped out unnoticed.","G294"]],"穿":[["穿红衣服的那个人是谁？","Chuān hóng yīfu de nà gèrén shì shéi?","Who is the person in the red clothes?","G175"],["多穿点，要不然会感冒。","Duō chuān diǎn, yàobùrán huì gǎnmào.","Wrap up, otherwise you will catch cold.","G408"]],"次":[["本次会议共有二十人参加。","Běn cì huìyì gòngyǒu èr shí rén cānjiā.","Twenty people attended this meeting in total.","G217"],["依照惯例，会议每月一次。","Yīzhào guànlì, huìyì měi yuè yī cì.","By convention the meeting is monthly.","G301"],["贵就贵吧，就这一次。","Guì jiù guì ba, jiù zhè yī cì.","Expensive it is, then — just this once.","G415"]],"从":[["从目前情况来看，问题不大。","Cóng mùqián qíngkuàng lái kàn, wèntí bù dà.","Judging from the current situation, it is not a big problem.","G313"],["从这一点来看，他是对的。","Cóng zhè yī diǎn lái kàn, tā shì duì de.","On this point he is right.","G313"],["从那以后再也没见过他。","Cóng nà yǐhòu zài yě méi jiànguo tā.","I never saw him again after that.","G344"]],"错":[["错了就错了，改过来就好。","Cuò le jiù cuò le, gǎi guòlái jiù hǎo.","A mistake is a mistake — just put it right.","G424"],["那倒是，是我错了。","Nà dàoshì, shì wǒ cuò le.","Fair point, I was wrong.","G390"]],"打":[["杯子被他给打碎了。","Bēizi bèi tā gěi dǎ suì le.","The cup got smashed by him.","G399"],["他买了一打鸡蛋。","Tā mǎi le yī dǎ jīdàn.","He bought a dozen eggs.","G214"],["门怎么都打不开。","Mén zěnme dōu dǎ bù kāi.","The door will not open no matter what.","G346"]],"打电话":[["要是有问题，就给我打电话。","Yàoshi yǒu wèntí, jiù gěi wǒ dǎ diànhuà.","If there is a problem, call me.","G199"],["我一到家就给你打电话。","Wǒ yī dào jiā jiù gěi nǐ dǎ diànhuà.","I'll call you as soon as I get home.","G117"],["他正在打电话。","Tā zhèngzài dǎ diànhuà.","He is on the phone right now.","G11"]],"打开":[["他打开门，走了进去。","Tā dǎkāi mén, zǒu le jìnqù.","He opened the door and went in.","G358"]],"打球":[["他喜欢打球、跑步什么的。","Tā xǐhuan dǎ qiú, pǎobù shénme de.","He likes ball games, running and the like.","G91"],["除了打球，他也喜欢游泳。","Chúle dǎ qiú, tā yě xǐhuan yóuyǒng.","Besides ball games he also likes swimming.","G168"],["下课以后我们去打球。","Xiàkè yǐhòu wǒmen qù dǎ qiú.","After class we go play ball.","G95"]],"大":[["经历过大风大浪的人不怕这个。","Jīnglì guò dà fēng dà làng de rén bù pà zhè gè.","Someone who has weathered storms is not afraid of this.","G234"],["雨不但没停，反而更大了。","Yǔ bùdàn méi tíng, fǎn'ér gèng dà le.","The rain did not stop; it got heavier.","G403"],["他们大吃大喝了一顿。","Tāmen dà chī dà hē le yī dùn.","They ate and drank their fill.","G234"]],"到":[["他东一句西一句，说不到点子上。","Tā dōng yī jù xī yī jù, shuō bù dào diǎnzi shàng.","He rambles without getting to the point.","G394"],["当我到家的时候，他已经走了。","Dāng wǒ dào jiā de shíhou, tā yǐjīng zǒu le.","When I got home, he had already left.","G69"],["这件事很重要，它关系到大家。","Zhè jiàn shì hěn zhòngyào, tā guānxì dào dàjiā.","This matter is important; it concerns everyone.","G357"]],"地":[["他昨天在图书馆认真地看书。","Tā zuótiān zài túshūguǎn rènzhēn de kàn shū.","He read attentively in the library yesterday.","G320"],["他一步一步地往上走。","Tā yī bù yī bù de wǎng shàng zǒu.","He climbed up step by step.","G163"],["他偷偷地看了我一眼。","Tā tōutōu de kàn le wǒ yīyǎn.","He stole a glance at me.","G294"]],"的":[["这不是钱的问题，而是原则问题。","Zhè bù shì qián de wèntí, ér shì yuánzé wèntí.","This is not about money but about principle.","G254"],["随着年龄的增长，他变得成熟了。","Suízhe niánlíng de zēngzhǎng, tā biàn dé chéngshú le.","As he grew older he matured.","G296"],["跟去年相比，今年的收入增加了。","Gēn qùnián xiāngbǐ, jīnnián de shōurù zēngjiā le.","Compared with last year, income has risen.","G330"]],"等":[["我明天早上八点在楼下等你。","Wǒ míngtiān zǎoshang bā diǎn zài lóu xià děng nǐ.","I will wait for you downstairs at eight tomorrow morning.","G320"],["我喜欢苹果、香蕉等水果。","Wǒ xǐhuan píngguǒ, xiāngjiāo děng shuǐguǒ.","I like fruit such as apples and bananas.","G83"],["我等他等了一个小时。","Wǒ děng tā děng le yī gè xiǎoshí.","I waited an hour for him.","G189"]],"地方":[["这个地方去不得。","Zhè gè dìfang qù bù dé.","That place must not be visited.","G322"]],"弟弟":[["蛋糕被弟弟吃完了。","Dàngāo bèi dìdi chī wánle.","The cake was eaten up by my younger brother.","G185"]],"第":[["我们学第五课。","Wǒmen xué dì wǔ kè.","We are studying Lesson 5.","G120"],["这是第三次了。","Zhè shì dì sān cì le.","That's the third time.","G131"],["他是第一名。","Tā shì dì yī míng.","He came first.","G120"]],"点":[["要是早点出发就好了，否则会迟到。","Yàoshi zǎo diǎn chūfā jiù hǎo le, fǒuzé huì chídào.","Better to set off early, otherwise we will be late.","G334"],["既然你不舒服，就早点儿休息吧。","Jìrán nǐ bù shūfu, jiù zǎo diǎn ér xiūxi ba.","Since you are unwell, get some rest.","G266"],["他每天早起，为的是多学一点。","Tā měi tiān zǎo qǐ, wèi de shì duō xué yī diǎn.","He gets up early in order to study more.","G339"]],"电话":[["要是有问题，就给我打电话。","Yàoshi yǒu wèntí, jiù gěi wǒ dǎ diànhuà.","If there is a problem, call me.","G199"],["我一到家就给你打电话。","Wǒ yī dào jiā jiù gěi nǐ dǎ diànhuà.","I'll call you as soon as I get home.","G117"],["他正在打电话。","Tā zhèngzài dǎ diànhuà.","He is on the phone right now.","G11"]],"电脑":[["这是新买的电脑。","Zhè shì xīn mǎi de diànnǎo.","This is a newly bought computer.","G27"],["这台电脑五千块。","Zhè tái diànnǎo wǔ qiān kuài.","This computer costs 5,000 yuan.","G57"],["我买了一台电脑。","Wǒ mǎi le yī tái diànnǎo.","I bought a computer.","G139"]],"电视":[["他一边吃饭，一边看电视。","Tā yībiān chīfàn, yībiān kàn diànshì.","He eats while watching TV.","G39"],["先做作业，然后看电视。","Xiān zuò zuòyè, ránhòu kàn diànshì.","First do homework, then watch TV.","G110"],["我看电视。","Wǒ kàn diànshì.","I watch TV.","G26"]],"电影":[["我看了两次电影。","Wǒ kàn le liǎng cì diànyǐng.","I saw a film twice.","G100"]],"东":[["他东一句西一句，说不到点子上。","Tā dōng yī jù xī yī jù, shuō bù dào diǎnzi shàng.","He rambles without getting to the point.","G394"],["桌上东一本，西一本。","Zhuō shàng dōng yī běn, xī yī běn.","Books lay scattered all over the table.","G393"],["东一堆西一堆，很乱。","Dōng yī duī xī yī duī, hěn luàn.","Piles here and there — a real mess.","G394"]],"东西":[["这些东西以后用得着。","Zhèxiē dōngxi yǐhòu yòngdezháo.","These things will come in useful later.","G312"],["我去商店买东西。","Wǒ qù shāngdiàn mǎi dōngxi.","I go to the shop to buy things.","G105"]],"动":[["连大人都搬不动，孩子更不行了。","Lián dàren dōu bān bù dòng, háizi gèng bùxíng le.","Even an adult cannot lift it, let alone a child.","G405"]],"都":[["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["连大人都搬不动，孩子更不行了。","Lián dàren dōu bān bù dòng, háizi gèng bùxíng le.","Even an adult cannot lift it, let alone a child.","G405"],["或者你来，或者我去，都可以。","Huòzhě nǐ lái, huòzhě wǒ qù, dōu kěyǐ.","Either you come or I go — both are fine.","G259"]],"读":[["老师让我们读课文。","Lǎoshī ràng wǒmen dú kèwén.","The teacher had us read the text.","G187"]],"读书":[["除工作外，他还爱读书。","Chú gōngzuò wài, tā hái ài dúshū.","Besides work, he also loves reading.","G376"]],"对":[["对学生来说，学习最重要。","Duì xuéshēng lái shuō, xuéxí zuì zhòngyào.","For students, study matters most.","G170"],["从这一点来看，他是对的。","Cóng zhè yī diǎn lái kàn, tā shì duì de.","On this point he is right.","G313"],["对我来说，这不是问题。","Duì wǒ lái shuō, zhè bù shì wèntí.","For me this is not a problem.","G170"]],"多":[["自从来到北京，我认识了很多朋友。","Zìcóng láidào Běijīng, wǒ rènshi le hěn duō péngyou.","Since coming to Beijing I have made many friends.","G151"],["他每天早起，为的是多学一点。","Tā měi tiān zǎo qǐ, wèi de shì duō xué yī diǎn.","He gets up early in order to study more.","G339"],["很多人，甚至孩子都知道。","Hěn duō rén, shènzhì háizi dōu zhīdào.","Many people, even children, know it.","G258"]],"多少":[["这个多少钱？","Zhè gè duōshao qián?","How much is this?","G43"],["一共多少钱？","Yīgòng duōshao qián?","How much altogether?","G62"]],"二":[["三分之二的学生通过了考试。","Sān fēn zhī èr de xuéshēng tōngguò le kǎoshì.","Two-thirds of the students passed.","G273"],["本次会议共有二十人参加。","Běn cì huìyì gòngyǒu èr shí rén cānjiā.","Twenty people attended this meeting in total.","G217"],["他说一是一，说二是二。","Tā shuō yī shì yī, shuō èr shì èr.","He means exactly what he says.","G279"]],"饭":[["放着饭不吃，光吃零食。","Fàng zhe fàn bù chī, guāng chī língshí.","A meal sitting there and he eats only snacks.","G422"],["我们吃了一顿好饭。","Wǒmen chī le yī dùn hǎo fàn.","We had a good meal.","G140"],["他甚至连饭都没吃。","Tā shènzhì lián fàn dōu méi chī.","He didn't even eat.","G231"]],"房间":[["他从房间里走出来了。","Tā cóng fángjiān lǐ zǒu chūlái le.","He walked out of the room.","G177"],["他在房间里走来走去。","Tā zài fángjiān lǐ zǒu lái zǒu qù.","He paced around the room.","G304"],["你把房间收拾收拾。","Nǐ bǎ fángjiān shōushi shōushi.","Give the room a tidy.","G249"]],"放":[["放着好好的路不走，偏走小道。","Fàng zhe hǎohǎo de lù bù zǒu, piān zǒu xiǎo dào.","A perfectly good road there, and he takes the back lane.","G422"],["车放着也是放着，你开走吧。","Chē fàng zhe yě shì fàng zhe, nǐ kāi zǒu ba.","The car is just sitting there — take it.","G350"],["书我看完了，放在桌上了。","Shū wǒ kàn wánle, fàng zài zhuō shàng le.","I finished the book and put it on the table.","G358"]],"飞机":[["他坐飞机去上海。","Tā zuò fēijī qù shàng hǎi.","He flies to Shanghai.","G105"]],"非常":[["本次会议非常重要。","Běn cì huìyì fēicháng zhòngyào.","This meeting is very important.","G361"],["这个菜非常好吃。","Zhè gè cài fēicháng hǎochī.","This dish is extremely tasty.","G9"],["这里非常安静。","Zhèlǐ fēicháng ānjìng.","It is extremely quiet here.","G89"]],"风":[["经历过大风大浪的人不怕这个。","Jīnglì guò dà fēng dà làng de rén bù pà zhè gè.","Someone who has weathered storms is not afraid of this.","G234"],["大风把树刮倒了。","Dà fēng bǎ shù guā dǎo le.","The gale blew the tree down.","G398"]],"干":[["什么累不累的，先干完再说。","Shénme lèi bù lèi de, xiān gān wán zàishuō.","Never mind tired — finish it first.","G356"],["房间干干净净的。","Fángjiān gān gānjìng jìng de.","The room is spotlessly clean.","G56"]],"干净":[["房间干干净净的。","Fángjiān gān gānjìng jìng de.","The room is spotlessly clean.","G56"],["他的房间很干净。","Tā de fángjiān hěn gānjìng.","His room is very clean.","G89"],["衣服洗干净了。","Yīfu xǐ gānjìng le.","The clothes have been washed clean.","G327"]],"高":[["她高高兴兴地走了。","Tā gāo gāoxìng xīng de zǒu le.","She left cheerfully.","G56"],["他比我高五厘米。","Tā bǐ wǒ gāo wǔ límǐ.","He is five centimetres taller than me.","G101"],["这棵树有十米高。","Zhè kē shù yǒu shí mǐ gāo.","This tree is ten metres tall.","G103"]],"高兴":[["只要你来，我就很高兴。","Zhǐyào nǐ lái, wǒ jiù hěn gāoxìng.","As long as you come, I'll be happy.","G115"],["他时而高兴，时而沉默。","Tā shí'ér gāoxìng, shí'ér chénmò.","He is cheerful at times and silent at others.","G400"],["他高兴得像孩子似的。","Tā gāoxìng dé xiàng háizi shìde.","He was as happy as a child.","G232"]],"哥哥":[["不管怎样说，他是你哥哥。","Bùguǎn zěnyàng shuō, tā shì nǐ gēge.","Whatever you say, he is your brother.","G352"]],"个":[["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["对于这个问题，我有不同看法。","Duìyú zhè gè wèntí, wǒ yǒu bù tóng kànfǎ.","On this question I take a different view.","G225"],["经历过大风大浪的人不怕这个。","Jīnglì guò dà fēng dà làng de rén bù pà zhè gè.","Someone who has weathered storms is not afraid of this.","G234"]],"给":[["要是有问题，就给我打电话。","Yàoshi yǒu wèntí, jiù gěi wǒ dǎ diànhuà.","If there is a problem, call me.","G199"],["我一到家就给你打电话。","Wǒ yī dào jiā jiù gěi nǐ dǎ diànhuà.","I'll call you as soon as I get home.","G117"],["他把钥匙给弄丢了。","Tā bǎ yàoshi gěi nòng diū le.","He went and lost the key.","G249"]],"跟":[["跟去年相比，今年的收入增加了。","Gēn qùnián xiāngbǐ, jīnnián de shōurù zēngjiā le.","Compared with last year, income has risen.","G330"],["我的手机跟你的一样。","Wǒ de shǒujī gēn nǐ de yīyàng.","My phone is the same as yours.","G107"],["我跟朋友一起去。","Wǒ gēn péngyou yīqǐ qù.","I am going with a friend.","G17"]],"工作":[["一方面要工作，另一方面要照顾家人。","Yīfāngmiàn yào gōngzuò, lìng yīfāngmiàn yào zhàogù jiārén.","On one hand there is work, on the other looking after family.","G192"],["他努力工作，从而获得了成功。","Tā nǔlì gōngzuò, cóng'ér huòdé le chénggōng.","He worked hard and thereby succeeded.","G302"],["尽管很累，但是他还在工作。","Jǐnguǎn hěn lèi, dànshì tā hái zài gōngzuò.","Even though he is tired he is still working.","G332"]],"关上":[["他把门轻轻地关上了。","Tā bǎ mén qīng qīng de guānshang le.","He closed the door gently.","G326"],["请把窗户关上。","Qǐng bǎ chuānghu guānshang.","Please close the window.","G157"]],"贵":[["这里的菜好吃，而且不贵。","Zhèlǐ de cài hǎochī, érqiě bù guì.","The food here is tasty, and cheap too.","G111"],["菜很好吃，不过有点儿贵。","Cài hěn hǎochī, bùguò yǒudiǎnr guì.","The food is tasty, though a bit pricey.","G113"],["什么贵不贵的，喜欢就买。","Shénme guì bù guì de, xǐhuan jiù mǎi.","Forget expensive — buy it if you like it.","G356"]],"过":[["经历过大风大浪的人不怕这个。","Jīnglì guò dà fēng dà làng de rén bù pà zhè gè.","Someone who has weathered storms is not afraid of this.","G234"],["自从那以后，他再也没来过。","Zìcóng nà yǐhòu, tā zài yě méi lái guò.","Ever since then he has never come again.","G151"],["除了小王，我们都去过。","Chúle xiǎo wáng, wǒmen dōu qù guò.","All of us except Xiao Wang have been.","G168"]],"还":[["他不仅会做饭，还会做菜谱。","Tā bùjǐn huì zuòfàn, hái huì zuò cài pǔ.","He can not only cook but even write recipes.","G196"],["还朋友呢，一点儿都不帮忙。","Hái péngyou ne, yīdiǎnr dōu bù bāngmáng.","Some friend — no help at all.","G284"],["尽管很累，但是他还在工作。","Jǐnguǎn hěn lèi, dànshì tā hái zài gōngzuò.","Even though he is tired he is still working.","G332"]],"还是":[["外面下雨，还是别去了吧。","Wàimiàn xià yǔ, háishi bié qù le ba.","It's raining — better not go.","G93"],["你是去北京，还是去上海？","Nǐ shì qù Běijīng, háishi qù shàng hǎi?","Are you going to Beijing or Shanghai?","G112"],["我再三考虑，还是决定去。","Wǒ zàisān kǎolǜ, háishi juédìng qù.","After much thought I decided to go after all.","G219"]],"还有":[["此外，还有一个问题。","Cǐwài, hái yǒu yī gè wèntí.","Besides this, there is another issue.","G361"],["离考试还有三天。","Lí kǎoshì hái yǒu sān tiān.","There are three days left until the exam.","G75"]],"孩子":[["连大人都搬不动，孩子更不行了。","Lián dàren dōu bān bù dòng, háizi gèng bùxíng le.","Even an adult cannot lift it, let alone a child.","G405"],["很多人，甚至孩子都知道。","Hěn duō rén, shènzhì háizi dōu zhīdào.","Many people, even children, know it.","G258"],["连小孩子都懂这个道理。","Lián xiǎo háizi dōu dǒng zhè gè dàolǐ.","Even children understand this.","G277"]],"汉语":[["为了学好汉语，他每天听录音。","Wèile xué hǎo Hànyǔ, tā měi tiān tīng lùyīn.","To master Chinese he listens to recordings daily.","G156"],["自去年以来，他一直在学汉语。","Zì qùnián yǐlái, tā yīzhí zài xué Hànyǔ.","Since last year he has been studying Chinese.","G241"],["他会说英语，也会说汉语。","Tā huì shuō Yīngyǔ, yě huì shuō Hànyǔ.","He speaks English, and Chinese too.","G190"]],"汉字":[["他写汉字写得很漂亮。","Tā xiě Hànzì xiě dé hěn piàoliang.","He writes characters beautifully.","G189"]],"好":[["要是早点出发就好了，否则会迟到。","Yàoshi zǎo diǎn chūfā jiù hǎo le, fǒuzé huì chídào.","Better to set off early, otherwise we will be late.","G334"],["他准备得很充分，所以考得很好。","Tā zhǔnbèi dé hěn chōngfèn, suǒyǐ kǎo dé hěn hǎo.","He prepared thoroughly, so he did well in the exam.","G201"],["为了学好汉语，他每天听录音。","Wèile xué hǎo Hànyǔ, tā měi tiān tīng lùyīn.","To master Chinese he listens to recordings daily.","G156"]],"好吃":[["这里的菜好吃，而且不贵。","Zhèlǐ de cài hǎochī, érqiě bù guì.","The food here is tasty, and cheap too.","G111"],["菜很好吃，不过有点儿贵。","Cài hěn hǎochī, bùguò yǒudiǎnr guì.","The food is tasty, though a bit pricey.","G113"],["这个菜又好吃又便宜。","Zhè gè cài yòu hǎochī yòu piányi.","This dish is both tasty and cheap.","G94"]],"好听":[["她唱歌唱得很好听。","Tā chànggē chàng dé hěn hǎotīng.","She sings beautifully.","G99"]],"号":[["今天是五月八号。","Jīntiān shì wǔ yuè bā hào.","Today is 8 May.","G44"],["明天三月八号。","Míngtiān sān yuè bā hào.","Tomorrow is 8 March.","G102"]],"喝":[["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["他们大吃大喝了一顿。","Tāmen dà chī dà hē le yī dùn.","They ate and drank their fill.","G234"],["你喝茶还是喝咖啡？","Nǐ hē chá háishi hē kāfēi?","Will you have tea or coffee?","G19"]],"和":[["我喜欢苹果和香蕉。","Wǒ xǐhuan píngguǒ hé xiāngjiāo.","I like apples and bananas.","G19"],["水由氢和氧组成。","Shuǐ yóu 氢 hé yǎng zǔchéng.","Water is composed of hydrogen and oxygen.","G242"],["我和他是同学。","Wǒ hé tā shì tóngxué.","He and I are classmates.","G17"]],"很":[["自从来到北京，我认识了很多朋友。","Zìcóng láidào Běijīng, wǒ rènshi le hěn duō péngyou.","Since coming to Beijing I have made many friends.","G151"],["他准备得很充分，所以考得很好。","Tā zhǔnbèi dé hěn chōngfèn, suǒyǐ kǎo dé hěn hǎo.","He prepared thoroughly, so he did well in the exam.","G201"],["这里不光风景好，而且很安静。","Zhèlǐ bùguāng fēngjǐng hǎo, érqiě hěn ānjìng.","The scenery here is lovely, and it is quiet too.","G196"]],"花":[["他送了她一朵花。","Tā sòng le tā yī duǒ huā.","He gave her a flower.","G289"]],"话":[["话音刚落，掌声便响了起来。","Huà yīn gāng luò, zhǎngshēng biàn xiǎng le qǐlái.","He had barely finished when the applause began.","G402"],["他说了一番话，很有道理。","Tā shuō le yīfān huà, hěn yǒu dàolǐ.","He said a piece that made a lot of sense.","G363"],["他听了这话很生气。","Tā tīng le zhè huà hěn shēngqì.","Hearing that, he got angry.","G328"]],"坏":[["好也是它，坏也是它。","Hǎo yě shì tā, huài yě shì tā.","It is the good of it and the bad of it alike.","G349"],["这件事把他急坏了。","Zhè jiàn shì bǎ tā jí huài le.","This matter made him frantic.","G398"],["我累坏了。","Wǒ lèi huài le.","I am worn out.","G323"]],"回答":[["首先介绍自己，然后回答问题。","Shǒuxiān jièshào zìjǐ, ránhòu huídá wèntí.","First introduce yourself, then answer questions.","G194"]],"回家":[["天下起雨来，于是我们回家了。","Tiānxià qǐ yǔ lái, yúshì wǒmen huí jiā le.","It began to rain, so we went home.","G257"],["妈妈叫我早点儿回家。","Māma jiào wǒ zǎo diǎn ér huí jiā.","Mum told me to come home early.","G187"],["下了课就回家。","Xià le kè jiù huí jiā.","Go straight home after class.","G203"]],"回来":[["他三四天以后回来。","Tā sān sì tiān yǐhòu huílái.","He will be back in three or four days.","G204"]],"回去":[["请把书拿回去。","Qǐng bǎ shū ná huíqù.","Please take the book back.","G177"]],"会":[["要是早点出发就好了，否则会迟到。","Yàoshi zǎo diǎn chūfā jiù hǎo le, fǒuzé huì chídào.","Better to set off early, otherwise we will be late.","G334"],["他不但会英语，而且会法语。","Tā bùdàn huì Yīngyǔ, érqiě huì Fǎyǔ.","He speaks not only English but also French.","G111"],["他不仅会做饭，还会做菜谱。","Tā bùjǐn huì zuòfàn, hái huì zuò cài pǔ.","He can not only cook but even write recipes.","G196"]],"火车":[["为了赶上火车，他跑得很快。","Wèile gǎnshàng huǒchē, tā pǎo dé hěn kuài.","He ran fast to catch the train.","G202"],["火车快要开了。","Huǒchē kuàiyào kāi le.","The train is about to leave.","G130"]],"鸡蛋":[["他买了一打鸡蛋。","Tā mǎi le yī dǎ jīdàn.","He bought a dozen eggs.","G214"]],"几":[["墙上写有几个大字。","Qiáng shàng xiě yǒu jǐ gè dà zì.","Several large characters are written on the wall.","G325"]],"记":[["请把地址记下来。","Qǐng bǎ dìzhǐ jì xiàlái.","Please write the address down.","G248"]],"记住":[["请记住这个号码。","Qǐng jìzhù zhè gè hàomǎ.","Please memorise this number.","G176"]],"家":[["当我到家的时候，他已经走了。","Dāng wǒ dào jiā de shíhou, tā yǐjīng zǒu le.","When I got home, he had already left.","G69"],["我一到家就给你打电话。","Wǒ yī dào jiā jiù gěi nǐ dǎ diànhuà.","I'll call you as soon as I get home.","G117"],["我再也不去那家店了。","Wǒ zài yě bù qù nà jiā diàn le.","I will never go to that shop again.","G344"]],"家里":[["家里来客人了。","Jiā li lái kèrén le.","Guests have arrived at the house.","G319"]],"家人":[["一方面要工作，另一方面要照顾家人。","Yīfāngmiàn yào gōngzuò, lìng yīfāngmiàn yào zhàogù jiārén.","On one hand there is work, on the other looking after family.","G192"]],"见":[["你听得见吗？","Nǐ tīng dé jiàn ma?","Can you hear it?","G178"]],"教":[["老师教我们汉语。","Lǎoshī jiāo wǒmen Hànyǔ.","The teacher teaches us Chinese.","G109"]],"叫":[["妈妈叫我早点儿回家。","Māma jiào wǒ zǎo diǎn ér huí jiā.","Mum told me to come home early.","G187"],["大家都叫他小李。","Dàjiā dōu jiào tā xiǎo lǐ.","Everyone calls him Xiao Li.","G252"],["有事叫我就是了。","Yǒushì jiào wǒ jiùshì le.","Just call me if you need anything.","G283"]],"介绍":[["首先介绍自己，然后回答问题。","Shǒuxiān jièshào zìjǐ, ránhòu huídá wèntí.","First introduce yourself, then answer questions.","G194"],["请向大家介绍一下。","Qǐng xiàng dàjiā jièshào yī xià.","Please introduce yourself to everyone.","G154"]],"今年":[["跟去年相比，今年的收入增加了。","Gēn qùnián xiāngbǐ, jīnnián de shōurù zēngjiā le.","Compared with last year, income has risen.","G330"],["他今年二十岁。","Tā jīnnián èr shí suì.","He is twenty this year.","G96"]],"今天":[["没有你就没有今天的我。","Méiyǒu nǐ jiù méiyǒu jīntiān de wǒ.","Without you I would not be who I am today.","G341"],["或者今天，或者明天。","Huòzhě jīntiān, huòzhě míngtiān.","Either today or tomorrow.","G259"],["或是今天，或是明天。","Huòshì jīntiān, huòshì míngtiān.","Either today or tomorrow.","G331"]],"进来":[["请一个一个地进来。","Qǐng yī gè yī gè de jìnlái.","Please come in one at a time.","G163"],["我可以进来吗？","Wǒ kěyǐ jìnlái ma?","May I come in?","G49"],["他走进来了。","Tā zǒujìn lái le.","He walked in.","G98"]],"进去":[["他打开门，走了进去。","Tā dǎkāi mén, zǒu le jìnqù.","He opened the door and went in.","G358"],["任何人都不能进去。","Rènhé rén dōu bù néng jìnqù.","No one at all may enter.","G138"],["从这个门进去。","Cóng zhè gè mén jìnqù.","Go in through this door.","G72"]],"九":[["从九点到十二点上课。","Cóng jiǔ diǎn dào shí èr diǎn shàngkè.","Class runs from nine to twelve.","G15"],["他九点才来。","Tā jiǔ diǎn cái lái.","He did not come until nine.","G68"]],"就":[["如果下雨，我们就不去，而是在家看书。","Rúguǒ xià yǔ, wǒmen jiù bù qù, ér shì zàijiā kàn shū.","If it rains we will stay home and read instead.","G343"],["如果天晴就去公园，如果下雨就在家看书。","Rúguǒ tiān qíng jiù qù gōngyuán, rúguǒ xià yǔ jiù zàijiā kàn shū.","If it is fine we go to the park; if it rains we read at home.","G412"],["要是早点出发就好了，否则会迟到。","Yàoshi zǎo diǎn chūfā jiù hǎo le, fǒuzé huì chídào.","Better to set off early, otherwise we will be late.","G334"]],"觉得":[["我觉得这个办法很好。","Wǒ juéde zhè gè bànfǎ hěn hǎo.","I think this method is good.","G174"]],"开":[["车放着也是放着，你开走吧。","Chē fàng zhe yě shì fàng zhe, nǐ kāi zǒu ba.","The car is just sitting there — take it.","G350"],["门怎么都打不开。","Mén zěnme dōu dǎ bù kāi.","The door will not open no matter what.","G346"],["火车快要开了。","Huǒchē kuàiyào kāi le.","The train is about to leave.","G130"]],"开会":[["我替他去开会。","Wǒ tì tā qù kāihuì.","I am attending the meeting in his place.","G227"]],"看":[["如果下雨，我们就不去，而是在家看书。","Rúguǒ xià yǔ, wǒmen jiù bù qù, ér shì zàijiā kàn shū.","If it rains we will stay home and read instead.","G343"],["如果天晴就去公园，如果下雨就在家看书。","Rúguǒ tiān qíng jiù qù gōngyuán, rúguǒ xià yǔ jiù zàijiā kàn shū.","If it is fine we go to the park; if it rains we read at home.","G412"],["周末他不是看书，就是运动。","Zhōumò tā bù shì kàn shū, jiùshì yùndòng.","At weekends he either reads or exercises.","G197"]],"考":[["他准备得很充分，所以考得很好。","Tā zhǔnbèi dé hěn chōngfèn, suǒyǐ kǎo dé hěn hǎo.","He prepared thoroughly, so he did well in the exam.","G201"],["为了考好，他复习到很晚。","Wèile kǎo hǎo, tā fùxí dào hěn wǎn.","To do well he revised late into the night.","G202"],["你要努力，否则考不上。","Nǐ yào nǔlì, fǒuzé kǎo bù shàng.","Work hard, or you will not pass.","G261"]],"考试":[["三分之二的学生通过了考试。","Sān fēn zhī èr de xuéshēng tōngguò le kǎoshì.","Two-thirds of the students passed.","G273"],["离考试还有三天。","Lí kǎoshì hái yǒu sān tiān.","There are three days left until the exam.","G75"]],"课":[["开学以来，他没缺过课。","Kāixué yǐlái, tā méi quē guò kè.","He has not missed a class since term began.","G241"],["我们学第五课。","Wǒmen xué dì wǔ kè.","We are studying Lesson 5.","G120"],["下了课就回家。","Xià le kè jiù huí jiā.","Go straight home after class.","G203"]],"课文":[["老师让我们读课文。","Lǎoshī ràng wǒmen dú kèwén.","The teacher had us read the text.","G187"]],"口":[["他们家有五口人。","Tāmen jiā yǒu wǔ kǒu rén.","There are five people in his family.","G8"]],"块":[["这台电脑五千块。","Zhè tái diànnǎo wǔ qiān kuài.","This computer costs 5,000 yuan.","G57"],["这本书贵二十块。","Zhè běn shū guì èr shí kuài.","This book is twenty yuan more expensive.","G101"],["这个西瓜十五块。","Zhè gè xīguā shí wǔ kuài.","This watermelon is fifteen yuan.","G102"]],"快":[["在老师的帮助下，我进步很快。","Zài lǎoshī de bāngzhù xià, wǒ jìnbù hěn kuài.","With the teacher's help I improved fast.","G244"],["票很快卖完了，可见很受欢迎。","Piào hěn kuài mài wánle, kějiàn hěn shòu huānyíng.","The tickets sold out fast — clearly it is popular.","G267"],["为了赶上火车，他跑得很快。","Wèile gǎnshàng huǒchē, tā pǎo dé hěn kuài.","He ran fast to catch the train.","G202"]],"来":[["因为他病了，所以虽然想来，也没能来。","Yīnwèi tā bìng le, suǒyǐ suīrán xiǎng lái, yě méi néng lái.","Because he was ill, although he wanted to come, he could not.","G343"],["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["天下起雨来，于是我们回家了。","Tiānxià qǐ yǔ lái, yúshì wǒmen huí jiā le.","It began to rain, so we went home.","G257"]],"来到":[["自从来到北京，我认识了很多朋友。","Zìcóng láidào Běijīng, wǒ rènshi le hěn duō péngyou.","Since coming to Beijing I have made many friends.","G151"]],"老":[["老王是我的同事。","Lǎo wáng shì wǒ de tóngshì.","Lao Wang is my colleague.","G131"]],"老师":[["在老师的帮助下，我进步很快。","Zài lǎoshī de bāngzhù xià, wǒ jìnbù hěn kuài.","With the teacher's help I improved fast.","G244"],["他既是老师，也是作家。","Tā jì shì lǎoshī, yě shì zuòjiā.","He is both a teacher and a writer.","G255"],["还老师呢，这都不知道。","Hái lǎoshī ne, zhè dōu bùzhī dào.","Some teacher — you do not even know that.","G284"]],"了":[["因为他病了，所以虽然想来，也没能来。","Yīnwèi tā bìng le, suǒyǐ suīrán xiǎng lái, yě méi néng lái.","Because he was ill, although he wanted to come, he could not.","G343"],["自从来到北京，我认识了很多朋友。","Zìcóng láidào Běijīng, wǒ rènshi le hěn duō péngyou.","Since coming to Beijing I have made many friends.","G151"],["要是早点出发就好了，否则会迟到。","Yàoshi zǎo diǎn chūfā jiù hǎo le, fǒuzé huì chídào.","Better to set off early, otherwise we will be late.","G334"]],"累":[["尽管很累，但是他还在工作。","Jǐnguǎn hěn lèi, dànshì tā hái zài gōngzuò.","Even though he is tired he is still working.","G332"],["什么累不累的，先干完再说。","Shénme lèi bù lèi de, xiān gān wán zàishuō.","Never mind tired — finish it first.","G356"],["虽然很累，但是很开心。","Suīrán hěn lèi, dànshì hěn kāixīn.","Although it was tiring, it was fun.","G78"]],"冷":[["天气一会儿冷，一会儿热。","Tiānqì yīhuìr lěng, yīhuìr rè.","The weather is cold one moment and hot the next.","G191"],["雨停了，天却更冷了。","Yǔ tíng le, tiān què gèng lěng le.","The rain stopped, but it got colder.","G220"],["天气一天比一天冷。","Tiānqì yī tiān bǐ yī tiān lěng.","It gets colder by the day.","G240"]],"里":[["他从房间里走出来了。","Tā cóng fángjiān lǐ zǒu chūlái le.","He walked out of the room.","G177"],["教室里走了两个学生。","Jiàoshì lǐ zǒu le liǎng gè xuéshēng.","Two students left the classroom.","G251"],["他在房间里走来走去。","Tā zài fángjiān lǐ zǒu lái zǒu qù.","He paced around the room.","G304"]],"两":[["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["这是我买的那两本新书。","Zhè shì wǒ mǎi de nà liǎng běn xīn shū.","These are the two new books I bought.","G247"],["这条路比那条近两公里。","Zhè tiáo lù bǐ nà tiáo jìn liǎng gōnglǐ.","This road is two kilometres shorter than that one.","G330"]],"楼下":[["我明天早上八点在楼下等你。","Wǒ míngtiān zǎoshang bā diǎn zài lóu xià děng nǐ.","I will wait for you downstairs at eight tomorrow morning.","G320"]],"路":[["放着好好的路不走，偏走小道。","Fàng zhe hǎohǎo de lù bù zǒu, piān zǒu xiǎo dào.","A perfectly good road there, and he takes the back lane.","G422"],["这条路比那条近两公里。","Zhè tiáo lù bǐ nà tiáo jìn liǎng gōnglǐ.","This road is two kilometres shorter than that one.","G330"],["沿着这条路一直走。","Yánzhe zhè tiáo lù yīzhí zǒu.","Keep going along this road.","G372"]],"路上":[["本想早点到，不料路上堵车。","Běn xiǎng zǎo diǎn dào, bùliào lùshang dǔchē.","I meant to arrive early, but there was traffic.","G379"]],"妈妈":[["妈妈叫我早点儿回家。","Māma jiào wǒ zǎo diǎn ér huí jiā.","Mum told me to come home early.","G187"],["妈妈做饭。","Māma zuòfàn.","Mum is cooking.","G29"]],"马上":[["我马上来。","Wǒ mǎshàng lái.","I'm coming right away.","G11"]],"吗":[["你不是已经知道了吗？","Nǐ bù shì yǐjīng zhīdào le ma?","Don't you already know?","G206"],["笑什么笑，很好玩吗？","Xiào shénme xiào, hěn hǎo wán ma?","What are you laughing at?","G355"],["我们明天去，好吗？","Wǒmen míngtiān qù, hǎo ma?","Let's go tomorrow, all right?","G124"]],"买":[["我买了水果、饮料什么的。","Wǒ mǎi le shuǐguǒ, yǐnliào shénme de.","I bought fruit, drinks and so on.","G91"],["买的买，看的看，很热闹。","Mǎi de mǎi, kàn de kàn, hěn rènao.","Some buying, some just looking — it was lively.","G317"],["什么贵不贵的，喜欢就买。","Shénme guì bù guì de, xǐhuan jiù mǎi.","Forget expensive — buy it if you like it.","G356"]],"忙":[["虽然很忙，但是他很快乐。","Suīrán hěn máng, dànshì tā hěn kuàilè.","Although he is busy, he is happy.","G113"],["他很忙，甚至没时间吃饭。","Tā hěn máng, shènzhì méi shíjiān chīfàn.","He is so busy he has no time even to eat.","G258"],["即使很忙，他也会来看我。","Jíshǐ hěn máng, tā yě huì lái kàn wǒ.","Even when busy he comes to see me.","G338"]],"没":[["因为他病了，所以虽然想来，也没能来。","Yīnwèi tā bìng le, suǒyǐ suīrán xiǎng lái, yě méi néng lái.","Because he was ill, although he wanted to come, he could not.","G343"],["要是有问题就说，否则我就当没事。","Yàoshi yǒu wèntí jiù shuō, fǒuzé wǒ jiù dāng méi shì.","Say so if there is a problem, otherwise I will assume all is well.","G334"],["自从那以后，他再也没来过。","Zìcóng nà yǐhòu, tā zài yě méi lái guò.","Ever since then he has never come again.","G151"]],"没关系":[["累就累点儿吧，没关系。","Lèi jiù lèi diǎn ér ba, méi guānxi.","It's a bit tiring, but never mind.","G210"]],"没什么":[["没什么好担心的。","Méi shénme hǎo dānxīn de.","There is nothing to worry about.","G280"]],"没有":[["由于时间不够，因此我们没有讨论完。","Yóuyú shíjiān bùgòu, yīncǐ wǒmen méiyǒu tǎolùn wán.","As time ran short, we did not finish the discussion.","G201"],["他不是不想去，而是没有时间。","Tā bù shì bù xiǎng qù, ér shì méiyǒu shíjiān.","It's not that he doesn't want to go — he has no time.","G254"],["他很努力，然而没有成功。","Tā hěn nǔlì, rán'ér méiyǒu chénggōng.","He worked hard; however, he did not succeed.","G260"]],"门":[["他把门轻轻地关上了。","Tā bǎ mén qīng qīng de guānshang le.","He closed the door gently.","G326"],["他打开门，走了进去。","Tā dǎkāi mén, zǒu le jìnqù.","He opened the door and went in.","G358"],["门怎么都打不开。","Mén zěnme dōu dǎ bù kāi.","The door will not open no matter what.","G346"]],"门口":[["门口站着两个人。","Ménkǒu zhàn zhe liǎng gèrén.","Two people are standing at the door.","G104"]],"们":[["同学们，请安静。","Tóngxué men, qǐng ānjìng.","Everyone, please be quiet.","G132"],["孩子们无忧无虑。","Háizi men wúyōu-wúlǜ.","The children are carefree.","G384"]],"名字":[["你叫什么名字？","Nǐ jiào shénme míngzi?","What's your name?","G4"]],"明白":[["想来想去还是不明白。","Xiǎng lái xiǎng qù háishi bù míngbai.","However much I think about it I still do not get it.","G304"],["他一说我就明白了。","Tā yī shuō wǒ jiù míngbai le.","The moment he spoke I understood.","G65"]],"明天":[["如果明天下雨，我们就不去了。","Rúguǒ míngtiān xià yǔ, wǒmen jiù bù qù le.","If it rains tomorrow, we won't go.","G114"],["我明天早上八点在楼下等你。","Wǒ míngtiān zǎoshang bā diǎn zài lóu xià děng nǐ.","I will wait for you downstairs at eight tomorrow morning.","G320"],["根据天气预报，明天有雨。","Gēnjù tiānqì yùbào, míngtiān yǒu yǔ.","According to the forecast it will rain tomorrow.","G228"]],"拿":[["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["拿这件事来说，他做得很好。","Ná zhè jiàn shì lái shuō, tā zuò dé hěn hǎo.","Take this matter — he handled it well.","G316"],["免费的，不拿白不拿。","Miǎnfèi de, bù ná bái bù ná.","It is free — you may as well take it.","G278"]],"哪儿":[["你想去哪儿就去哪儿。","Nǐ xiǎng qù nǎr jiù qù nǎr.","Go wherever you like.","G137"],["他在哪儿工作？","Tā zài nǎr gōngzuò?","Where does he work?","G4"],["我哪儿知道啊？","Wǒ nǎr zhīdào a?","How would I know?","G274"]],"那":[["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["这也不行，那也不好，很难办。","Zhè yě bùxíng, nà yě bù hǎo, hěn nán bàn.","This will not do and that is no good — it is hard to please him.","G425"],["自从那以后，他再也没来过。","Zìcóng nà yǐhòu, tā zài yě méi lái guò.","Ever since then he has never come again.","G151"]],"那儿":[["我从来没去过那儿。","Wǒ cónglái méi qù guò nàr.","I have never been there.","G144"]],"那些":[["那些书很贵。","Nàxiē shū hěn guì.","Those books are expensive.","G6"]],"南":[["这个房间朝南。","Zhè gè fángjiān cháo nán.","This room faces south.","G152"]],"难":[["这也不行，那也不好，很难办。","Zhè yě bùxíng, nà yě bù hǎo, hěn nán bàn.","This will not do and that is no good — it is hard to please him.","G425"],["一旦养成习惯，就很难改。","Yīdàn yǎngchéng xíguàn, jiù hěn nán gǎi.","Once a habit forms it is hard to change.","G333"],["无论多难，他都不放弃。","Wúlùn duō nán, tā dōu bù fàngqì.","However hard it is, he never gives up.","G265"]],"呢":[["还朋友呢，一点儿都不帮忙。","Hái péngyou ne, yīdiǎnr dōu bù bāngmáng.","Some friend — no help at all.","G284"],["这不是小事，还是大事呢。","Zhè bù shì xiǎo shì, háishi dàshì ne.","This is no small matter — it is a big one.","G404"],["带把伞吧，万一下雨呢。","Dài bǎ sǎn ba, wànyī xià yǔ ne.","Take an umbrella just in case it rains.","G263"]],"能":[["因为他病了，所以虽然想来，也没能来。","Yīnwèi tā bìng le, suǒyǐ suīrán xiǎng lái, yě méi néng lái.","Because he was ill, although he wanted to come, he could not.","G343"],["公是公，私是私，不能混。","Gōng shì gōng, sī shì sī, bù néng hùn.","Public and private must be kept apart.","G281"],["再难的题他也能做出来。","Zài nán de tí tā yě néng zuò chūlái.","He can solve even the hardest problem.","G342"]],"你":[["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["既然你不舒服，就早点儿休息吧。","Jìrán nǐ bù shūfu, jiù zǎo diǎn ér xiūxi ba.","Since you are unwell, get some rest.","G266"],["或者你来，或者我去，都可以。","Huòzhě nǐ lái, huòzhě wǒ qù, dōu kěyǐ.","Either you come or I go — both are fine.","G259"]],"年":[["他学汉语学了两年。","Tā xué Hànyǔ xué le liǎng nián.","He has studied Chinese for two years.","G181"],["他生于1990年。","Tā shēng yú1990 nián.","He was born in 1990.","G371"],["他学了三年汉语。","Tā xué le sān nián Hànyǔ.","He studied Chinese for three years.","G60"]],"您":[["您过奖了，不敢当。","Nín guòjiǎng le, bùgǎndāng.","You are too kind — I hardly deserve it.","G310"]],"旁边":[["他从我旁边走过。","Tā cóng wǒ pángbiān zǒuguò.","He walked past beside me.","G72"]],"跑":[["为了赶上火车，他跑得很快。","Wèile gǎnshàng huǒchē, tā pǎo dé hěn kuài.","He ran fast to catch the train.","G202"],["孩子偷偷跑出去了。","Háizi tōutōu pǎo chūqù le.","The child slipped out unnoticed.","G294"],["他比我跑得快。","Tā bǐ wǒ pǎo dé kuài.","He runs faster than me.","G188"]],"朋友":[["自从来到北京，我认识了很多朋友。","Zìcóng láidào Běijīng, wǒ rènshi le hěn duō péngyou.","Since coming to Beijing I have made many friends.","G151"],["还朋友呢，一点儿都不帮忙。","Hái péngyou ne, yīdiǎnr dōu bù bāngmáng.","Some friend — no help at all.","G284"],["我的中国朋友来了。","Wǒ de Zhōngguó péngyou lái le.","My Chinese friend has arrived.","G87"]],"票":[["票很快卖完了，可见很受欢迎。","Piào hěn kuài mài wánle, kějiàn hěn shòu huānyíng.","The tickets sold out fast — clearly it is popular.","G267"],["反正有票，不看白不看。","Fǎnzhèng yǒu piào, bù kàn bái bù kàn.","We have tickets anyway, so we may as well watch.","G278"],["好不容易买到了票。","Hǎo bùróng yì mǎi dào le piào.","I finally managed to get tickets.","G389"]],"七":[["他七点就来了。","Tā qī diǎn jiù lái le.","He came as early as seven.","G68"]],"起":[["天下起雨来，于是我们回家了。","Tiānxià qǐ yǔ lái, yúshì wǒmen huí jiā le.","It began to rain, so we went home.","G257"],["他每天早起，为的是多学一点。","Tā měi tiān zǎo qǐ, wèi de shì duō xué yī diǎn.","He gets up early in order to study more.","G339"],["我想出去，偏偏下起雨来。","Wǒ xiǎng chūqù, piānpiān xià qǐ yǔ lái.","I wanted to go out and of course it started raining.","G370"]],"起床":[["都十点了，快起床吧。","Dōu shí diǎn le, kuài qǐchuáng ba.","It's already ten — get up.","G209"]],"起来":[["话音刚落，掌声便响了起来。","Huà yīn gāng luò, zhǎngshēng biàn xiǎng le qǐlái.","He had barely finished when the applause began.","G402"],["这个字我怎么也想不起来。","Zhè gè zì wǒ zěnme yě xiǎng bù qǐlái.","I simply cannot recall this character.","G346"],["这件事看起来不简单。","Zhè jiàn shì kàn qǐlái bù jiǎndān.","This matter does not look simple.","G165"]],"汽车":[["我坐公共汽车去上班。","Wǒ zuò gōnggòng qìchē qù shàngbān.","I take the bus to work.","G186"]],"前":[["往前走五百米。","Wǎng qián zǒu wǔ bǎi mǐ.","Walk 500 metres straight ahead.","G70"]],"钱":[["这不是钱的问题，而是原则问题。","Zhè bù shì qián de wèntí, ér shì yuánzé wèntí.","This is not about money but about principle.","G254"],["说来说去，都是钱的问题。","Shuō lái shuō qù, dōu shì qián de wèntí.","It all comes back to money.","G423"],["这个多少钱？","Zhè gè duōshao qián?","How much is this?","G43"]],"钱包":[["钱包被偷了。","Qiánbāo bèi tōu le.","The wallet was stolen.","G250"]],"请":[["请写清楚，以便我们联系你。","Qǐng xiě qīngchu, yǐbiàn wǒmen liánxì nǐ.","Please write clearly so that we can contact you.","G340"],["若有问题，请联系我。","Ruò yǒu wèntí, qǐng liánxì wǒ.","If there are problems, please contact me.","G379"],["请向大家介绍一下。","Qǐng xiàng dàjiā jièshào yī xià.","Please introduce yourself to everyone.","G154"]],"请假":[["他因病请假。","Tā yīn bìng qǐngjià.","He took leave because of illness.","G375"]],"去":[["如果下雨，我们就不去，而是在家看书。","Rúguǒ xià yǔ, wǒmen jiù bù qù, ér shì zàijiā kàn shū.","If it rains we will stay home and read instead.","G343"],["如果天晴就去公园，如果下雨就在家看书。","Rúguǒ tiān qíng jiù qù gōngyuán, rúguǒ xià yǔ jiù zàijiā kàn shū.","If it is fine we go to the park; if it rains we read at home.","G412"],["如果明天下雨，我们就不去了。","Rúguǒ míngtiān xià yǔ, wǒmen jiù bù qù le.","If it rains tomorrow, we won't go.","G114"]],"去年":[["跟去年相比，今年的收入增加了。","Gēn qùnián xiāngbǐ, jīnnián de shōurù zēngjiā le.","Compared with last year, income has risen.","G330"],["自去年以来，他一直在学汉语。","Zì qùnián yǐlái, tā yīzhí zài xué Hànyǔ.","Since last year he has been studying Chinese.","G241"]],"热":[["天气一会儿冷，一会儿热。","Tiānqì yīhuìr lěng, yīhuìr rè.","The weather is cold one moment and hot the next.","G191"],["天气热得像夏天似的。","Tiānqì rè dé xiàng xiàtiān shìde.","It is as hot as summer.","G232"],["今天比昨天更热。","Jīntiān bǐ zuótiān gèng rè.","Today is even hotter than yesterday.","G61"]],"人":[["经历过大风大浪的人不怕这个。","Jīnglì guò dà fēng dà làng de rén bù pà zhè gè.","Someone who has weathered storms is not afraid of this.","G234"],["他去是去了，不过没找到人。","Tā qù shì qù le, bùguò méi zhǎodào rén.","He did go, but he did not find anyone.","G198"],["本次会议共有二十人参加。","Běn cì huìyì gòngyǒu èr shí rén cānjiā.","Twenty people attended this meeting in total.","G217"]],"认识":[["自从来到北京，我认识了很多朋友。","Zìcóng láidào Běijīng, wǒ rènshi le hěn duō péngyou.","Since coming to Beijing I have made many friends.","G151"]],"认真":[["他昨天在图书馆认真地看书。","Tā zuótiān zài túshūguǎn rènzhēn de kàn shū.","He read attentively in the library yesterday.","G320"],["老师表扬他学习认真。","Lǎoshī biǎoyáng tā xuéxí rènzhēn.","The teacher praised him for studying diligently.","G252"]],"三":[["三分之二的学生通过了考试。","Sān fēn zhī èr de xuéshēng tōngguò le kǎoshì.","Two-thirds of the students passed.","G273"],["这个城市有三百万人。","Zhè gè chéngshì yǒu sān bǎi wàn rén.","This city has three million people.","G57"],["他三四天以后回来。","Tā sān sì tiān yǐhòu huílái.","He will be back in three or four days.","G204"]],"山":[["我看得见那座山。","Wǒ kàndejiàn nà zuò shān.","I can see that mountain.","G136"]],"商店":[["我去商店买东西。","Wǒ qù shāngdiàn mǎi dōngxi.","I go to the shop to buy things.","G105"],["他去了商店。","Tā qù le shāngdiàn.","He went to the shop.","G41"]],"上":[["他东一句西一句，说不到点子上。","Tā dōng yī jù xī yī jù, shuō bù dào diǎnzi shàng.","He rambles without getting to the point.","G394"],["你是去北京，还是去上海？","Nǐ shì qù Běijīng, háishi qù shàng hǎi?","Are you going to Beijing or Shanghai?","G112"],["桌上有书、笔以及一些纸。","Zhuō shàng yǒu shū, bǐ yǐjí yīxiē zhǐ.","On the table are books, pens and some paper.","G230"]],"上班":[["我坐公共汽车去上班。","Wǒ zuò gōnggòng qìchē qù shàngbān.","I take the bus to work.","G186"]],"上课":[["从九点到十二点上课。","Cóng jiǔ diǎn dào shí èr diǎn shàngkè.","Class runs from nine to twelve.","G15"],["他因为生病没来上课。","Tā yīnwèi shēngbìng méi lái shàngkè.","He missed class because he was ill.","G116"],["我们八点半上课。","Wǒmen bā diǎn bàn shàngkè.","Our class starts at 8:30.","G44"]],"少":[["为了健康，你应该少吃盐。","Wèile jiànkāng, nǐ yīnggāi shǎo chī yán.","For your health you should eat less salt.","G156"]],"谁":[["穿红衣服的那个人是谁？","Chuān hóng yīfu de nà gèrén shì shéi?","Who is the person in the red clothes?","G175"],["无论谁来，都要登记。","Wúlùn shéi lái, dōu yào dēngjì.","Whoever comes must register.","G265"],["谁都知道这件事。","Shéi dōu zhīdào zhè jiàn shì.","Everyone knows about this.","G137"]],"身体":[["为了身体健康，他每天跑步。","Wèile shēntǐ jiànkāng, tā měi tiān pǎobù.","For his health he runs every day.","G76"],["运动对身体有好处。","Yùndòng duì shēntǐ yǒu hǎochù.","Exercise is good for your health.","G73"],["他的身体好起来了。","Tā de shēntǐ hǎo qǐlái le.","His health is picking up.","G397"]],"什么":[["什么累不累的，先干完再说。","Shénme lèi bù lèi de, xiān gān wán zàishuō.","Never mind tired — finish it first.","G356"],["我买了水果、饮料什么的。","Wǒ mǎi le shuǐguǒ, yǐnliào shénme de.","I bought fruit, drinks and so on.","G91"],["他喜欢打球、跑步什么的。","Tā xǐhuan dǎ qiú, pǎobù shénme de.","He likes ball games, running and the like.","G91"]],"生病":[["他因为生病没来上课。","Tā yīnwèi shēngbìng méi lái shàngkè.","He missed class because he was ill.","G116"],["他好像生病了。","Tā hǎoxiàng shēngbìng le.","He seems to be ill.","G67"]],"生气":[["生气归生气，事情还得办。","Shēngqì guī shēngqì, shìqing hái dé bàn.","Angry or not, the work still has to be done.","G351"],["他不但不生气，反而笑了。","Tā bùdàn bù shēngqì, fǎn'ér xiào le.","Far from being angry, he laughed.","G403"],["他听了这话很生气。","Tā tīng le zhè huà hěn shēngqì.","Hearing that, he got angry.","G328"]],"生日":[["他竟然忘了我的生日。","Tā jìngrán wàng le wǒ de shēngrì.","He actually forgot my birthday.","G223"]],"十":[["本次会议共有二十人参加。","Běn cì huìyì gòngyǒu èr shí rén cānjiā.","Twenty people attended this meeting in total.","G217"],["从九点到十二点上课。","Cóng jiǔ diǎn dào shí èr diǎn shàngkè.","Class runs from nine to twelve.","G15"],["他看上去只有二十岁。","Tā kàn shàngqù zhǐyǒu èr shí suì.","He looks only twenty.","G166"]],"时候":[["当我到家的时候，他已经走了。","Dāng wǒ dào jiā de shíhou, tā yǐjīng zǒu le.","When I got home, he had already left.","G69"],["早不来晚不来，偏偏这时候来。","Zǎo bù lái wǎn bù lái, piānpiān zhè shíhou lái.","Of all the times to turn up, he picks now.","G420"],["你什么时候来？","Nǐ shénme shíhou lái?","When are you coming?","G125"]],"时间":[["这样做一方面省时间，另一方面省钱。","Zhèyàng zuò yīfāngmiàn shěng shíjiān, lìng yīfāngmiàn shěngqián.","Doing it this way saves both time and money.","G192"],["由于时间不够，因此我们没有讨论完。","Yóuyú shíjiān bùgòu, yīncǐ wǒmen méiyǒu tǎolùn wán.","As time ran short, we did not finish the discussion.","G201"],["他不是不想去，而是没有时间。","Tā bù shì bù xiǎng qù, ér shì méiyǒu shíjiān.","It's not that he doesn't want to go — he has no time.","G254"]],"事":[["要是有问题就说，否则我就当没事。","Yàoshi yǒu wèntí jiù shuō, fǒuzé wǒ jiù dāng méi shì.","Say so if there is a problem, otherwise I will assume all is well.","G334"],["这件事很重要，它关系到大家。","Zhè jiàn shì hěn zhòngyào, tā guānxì dào dàjiā.","This matter is important; it concerns everyone.","G357"],["拿这件事来说，他做得很好。","Ná zhè jiàn shì lái shuō, tā zuò dé hěn hǎo.","Take this matter — he handled it well.","G316"]],"试":[["不管怎样说，我们得试试。","Bùguǎn zěnyàng shuō, wǒmen dé shì shì.","In any case we have to try.","G352"],["哪怕再难，我也要试试。","Nǎpà zài nán, wǒ yě yào shì shì.","However hard it is, I will try.","G268"],["难是难，我还是想试试。","Nán shì nán, wǒ háishi xiǎng shì shì.","Hard it may be, but I still want to try.","G416"]],"是":[["这不是钱的问题，而是原则问题。","Zhè bù shì qián de wèntí, ér shì yuánzé wèntí.","This is not about money but about principle.","G254"],["他不是在教室，就是在图书馆。","Tā bù shì zài jiàoshì, jiùshì zài túshūguǎn.","He is either in the classroom or in the library.","G197"],["他不是不想去，而是没有时间。","Tā bù shì bù xiǎng qù, ér shì méiyǒu shíjiān.","It's not that he doesn't want to go — he has no time.","G254"]],"是不是":[["他明天来，是不是？","Tā míngtiān lái, shì bu shì?","He's coming tomorrow, isn't he?","G127"],["他是不是老师？","Tā shì bu shì lǎoshī?","Is he a teacher?","G48"],["你是不是累了？","Nǐ shì bu shì lèi le?","Are you tired?","G127"]],"手":[["吃饭以前要洗手。","Chīfàn yǐqián yào xǐ shǒu.","Wash your hands before eating.","G95"],["他是一位多面手。","Tā shì yī wèi duō miàn shǒu.","He is an all-rounder.","G359"]],"手机":[["我的手机跟你的一样。","Wǒ de shǒujī gēn nǐ de yīyàng.","My phone is the same as yours.","G107"],["我的手机让人拿走了。","Wǒ de shǒujī ràng rén názǒu le.","Someone took my phone.","G185"],["他要买一个手机。","Tā yào mǎi yī gè shǒujī.","He wants to buy a phone.","G3"]],"书":[["如果下雨，我们就不去，而是在家看书。","Rúguǒ xià yǔ, wǒmen jiù bù qù, ér shì zàijiā kàn shū.","If it rains we will stay home and read instead.","G343"],["如果天晴就去公园，如果下雨就在家看书。","Rúguǒ tiān qíng jiù qù gōngyuán, rúguǒ xià yǔ jiù zàijiā kàn shū.","If it is fine we go to the park; if it rains we read at home.","G412"],["周末他不是看书，就是运动。","Zhōumò tā bù shì kàn shū, jiùshì yùndòng.","At weekends he either reads or exercises.","G197"]],"书包":[["我有一个红色的书包。","Wǒ yǒu yī gè hóngsè de shūbāo.","I have a red schoolbag.","G27"]],"树":[["这棵树有十米高。","Zhè kē shù yǒu shí mǐ gāo.","This tree is ten metres tall.","G103"],["院子里有三棵树。","Yuànzi lǐ yǒu sān kē shù.","There are three trees in the yard.","G214"],["大风把树刮倒了。","Dà fēng bǎ shù guā dǎo le.","The gale blew the tree down.","G398"]],"水":[["假如没有水，人就活不了。","Jiǎrú méiyǒu shuǐ, rén jiù huó bù le.","Without water people could not live.","G262"],["水由氢和氧组成。","Shuǐ yóu 氢 hé yǎng zǔchéng.","Water is composed of hydrogen and oxygen.","G242"],["他喝了一大杯水。","Tā hē le yī dà bēi shuǐ.","He drank a large glass of water.","G382"]],"水果":[["我喜欢苹果、香蕉等水果。","Wǒ xǐhuan píngguǒ, xiāngjiāo děng shuǐguǒ.","I like fruit such as apples and bananas.","G83"],["我买了水果、饮料什么的。","Wǒ mǎi le shuǐguǒ, yǐnliào shénme de.","I bought fruit, drinks and so on.","G91"],["他还买了水果。","Tā hái mǎi le shuǐguǒ.","He also bought fruit.","G13"]],"睡":[["早睡早起很重要。","Zǎo shuì zǎo qǐ hěn zhòngyào.","Going to bed and rising early matters.","G173"],["我睡了八个小时。","Wǒ shuì le bā gè xiǎoshí.","I slept eight hours.","G181"]],"睡觉":[["他正在睡觉呢。","Tā zhèngzài shuìjiào ne.","He is sleeping right now.","G42"]],"说":[["要是有问题就说，否则我就当没事。","Yàoshi yǒu wèntí jiù shuō, fǒuzé wǒ jiù dāng méi shì.","Say so if there is a problem, otherwise I will assume all is well.","G334"],["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["他东一句西一句，说不到点子上。","Tā dōng yī jù xī yī jù, shuō bù dào diǎnzi shàng.","He rambles without getting to the point.","G394"]],"说话":[["别说话！","Biéshuō huà!","Don't talk!","G34"]],"四":[["他三四天以后回来。","Tā sān sì tiān yǐhòu huílái.","He will be back in three or four days.","G204"]],"送":[["他送我一件礼物。","Tā sòng wǒ yī jiàn lǐwù.","He gave me a present.","G109"],["他送了她一朵花。","Tā sòng le tā yī duǒ huā.","He gave her a flower.","G289"]],"岁":[["他看上去只有二十岁。","Tā kàn shàngqù zhǐyǒu èr shí suì.","He looks only twenty.","G166"],["他比我大三岁。","Tā bǐ wǒ dà sān suì.","He is three years older than me.","G18"],["他今年二十岁。","Tā jīnnián èr shí suì.","He is twenty this year.","G96"]],"他":[["因为他病了，所以虽然想来，也没能来。","Yīnwèi tā bìng le, suǒyǐ suīrán xiǎng lái, yě méi néng lái.","Because he was ill, although he wanted to come, he could not.","G343"],["他准备得很充分，所以考得很好。","Tā zhǔnbèi dé hěn chōngfèn, suǒyǐ kǎo dé hěn hǎo.","He prepared thoroughly, so he did well in the exam.","G201"],["随着年龄的增长，他变得成熟了。","Suízhe niánlíng de zēngzhǎng, tā biàn dé chéngshú le.","As he grew older he matured.","G296"]],"他们":[["他们一问一答，配合得很好。","Tāmen yī wèn yī dá, pèihé dé hěn hǎo.","One asked, the other answered — they worked well together.","G235"],["他们大吃大喝了一顿。","Tāmen dà chī dà hē le yī dùn.","They ate and drank their fill.","G234"],["他们一个比一个聪明。","Tāmen yī gè bǐ yī gè cōngmíng.","Each of them is cleverer than the last.","G240"]],"她":[["她穿着一件漂亮的红色长裙。","Tā chuānzhuó yī jiàn piàoliang de hóngsè cháng qún.","She is wearing a beautiful long red dress.","G247"],["我喜欢音乐，她也喜欢。","Wǒ xǐhuan yīnyuè, tā yě xǐhuan.","I like music, and so does she.","G190"],["她把头发一甩就走了。","Tā bǎ tóufa yī shuǎi jiù zǒu le.","She tossed her hair and left.","G326"]],"太":[["好是好，就是太贵了。","Hǎo shì hǎo, jiùshì tài guì le.","It's good all right — just too expensive.","G198"],["你来得太早了。","Nǐ lái dé tài zǎo le.","You came too early.","G79"],["太贵了！","Tài guì le!","It's too expensive!","G9"]],"天":[["如果天晴就去公园，如果下雨就在家看书。","Rúguǒ tiān qíng jiù qù gōngyuán, rúguǒ xià yǔ jiù zàijiā kàn shū.","If it is fine we go to the park; if it rains we read at home.","G412"],["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["为了学好汉语，他每天听录音。","Wèile xué hǎo Hànyǔ, tā měi tiān tīng lùyīn.","To master Chinese he listens to recordings daily.","G156"]],"天气":[["由于天气不好，比赛取消了。","Yóuyú tiānqì bù hǎo, bǐsài qǔxiāo le.","Because of bad weather the match was cancelled.","G155"],["天气一会儿冷，一会儿热。","Tiānqì yīhuìr lěng, yīhuìr rè.","The weather is cold one moment and hot the next.","G191"],["根据天气预报，明天有雨。","Gēnjù tiānqì yùbào, míngtiān yǒu yǔ.","According to the forecast it will rain tomorrow.","G228"]],"听":[["为了学好汉语，他每天听录音。","Wèile xué hǎo Hànyǔ, tā měi tiān tīng lùyīn.","To master Chinese he listens to recordings daily.","G156"],["他没听懂，于是又问了一遍。","Tā méi tīng dǒng, yúshì yòu wèn le yī biàn.","He didn't understand, so he asked again.","G257"],["他听了这话很生气。","Tā tīng le zhè huà hěn shēngqì.","Hearing that, he got angry.","G328"]],"听见":[["他仿佛没听见。","Tā fǎngfú méi tīngjiàn.","It was as if he had not heard.","G369"]],"同学":[["我们班的同学都来了。","Wǒmen bān de tóngxué dōu lái le.","All the students in our class came.","G162"],["同学们，请安静。","Tóngxué men, qǐng ānjìng.","Everyone, please be quiet.","G132"],["我和他是同学。","Wǒ hé tā shì tóngxué.","He and I are classmates.","G17"]],"图书馆":[["他不是在教室，就是在图书馆。","Tā bù shì zài jiàoshì, jiùshì zài túshūguǎn.","He is either in the classroom or in the library.","G197"],["他昨天在图书馆认真地看书。","Tā zuótiān zài túshūguǎn rènzhēn de kàn shū.","He read attentively in the library yesterday.","G320"],["他常常去图书馆。","Tā chángcháng qù túshūguǎn.","He often goes to the library.","G12"]],"外":[["除工作外，他还爱读书。","Chú gōngzuò wài, tā hái ài dúshū.","Besides work, he also loves reading.","G376"]],"晚":[["早不来晚不来，偏偏这时候来。","Zǎo bù lái wǎn bù lái, piānpiān zhè shíhou lái.","Of all the times to turn up, he picks now.","G420"],["早不下晚不下，出门就下雨。","Zǎo bù xià wǎn bù xià, chūmén jiù xià yǔ.","It rains the moment I go out, never before or after.","G420"],["为了考好，他复习到很晚。","Wèile kǎo hǎo, tā fùxí dào hěn wǎn.","To do well he revised late into the night.","G202"]],"忘":[["他竟然忘了我的生日。","Tā jìngrán wàng le wǒ de shēngrì.","He actually forgot my birthday.","G223"],["你千万别忘了。","Nǐ qiānwàn bié wàng le.","Whatever you do, don't forget.","G149"],["我几乎忘了。","Wǒ jīhū wàng le.","I nearly forgot.","G222"]],"忘记":[["你老是忘记。","Nǐ lǎoshì wàngjì.","You keep forgetting.","G64"]],"问":[["他们一问一答，配合得很好。","Tāmen yī wèn yī dá, pèihé dé hěn hǎo.","One asked, the other answered — they worked well together.","G235"],["他没听懂，于是又问了一遍。","Tā méi tīng dǒng, yúshì yòu wèn le yī biàn.","He didn't understand, so he asked again.","G257"],["不问不知道，一问吓一跳。","Bù wèn bùzhī dào, yī wèn xià yī tiào.","You would never know until you ask — and then it startles you.","G417"]],"我":[["自从来到北京，我认识了很多朋友。","Zìcóng láidào Běijīng, wǒ rènshi le hěn duō péngyou.","Since coming to Beijing I have made many friends.","G151"],["要是有问题就说，否则我就当没事。","Yàoshi yǒu wèntí jiù shuō, fǒuzé wǒ jiù dāng méi shì.","Say so if there is a problem, otherwise I will assume all is well.","G334"],["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"]],"我们":[["如果下雨，我们就不去，而是在家看书。","Rúguǒ xià yǔ, wǒmen jiù bù qù, ér shì zàijiā kàn shū.","If it rains we will stay home and read instead.","G343"],["由于时间不够，因此我们没有讨论完。","Yóuyú shíjiān bùgòu, yīncǐ wǒmen méiyǒu tǎolùn wán.","As time ran short, we did not finish the discussion.","G201"],["如果明天下雨，我们就不去了。","Rúguǒ míngtiān xià yǔ, wǒmen jiù bù qù le.","If it rains tomorrow, we won't go.","G114"]],"五":[["这个小组由五个人组成。","Zhè gè xiǎozǔ yóu wǔ gèrén zǔchéng.","This group consists of five people.","G242"],["大概有五十人左右。","Dàgài yǒu wǔ shí rén zuǒyòu.","There are about fifty people.","G204"],["报名到本周五为止。","Bàomíng dào běn zhōu wǔ wéizhǐ.","Registration runs until this Friday.","G314"]],"西":[["他东一句西一句，说不到点子上。","Tā dōng yī jù xī yī jù, shuō bù dào diǎnzi shàng.","He rambles without getting to the point.","G394"],["桌上东一本，西一本。","Zhuō shàng dōng yī běn, xī yī běn.","Books lay scattered all over the table.","G393"],["东一堆西一堆，很乱。","Dōng yī duī xī yī duī, hěn luàn.","Piles here and there — a real mess.","G394"]],"洗":[["吃饭以前要洗手。","Chīfàn yǐqián yào xǐ shǒu.","Wash your hands before eating.","G95"],["衣服洗干净了。","Yīfu xǐ gānjìng le.","The clothes have been washed clean.","G327"]],"喜欢":[["我喜欢音乐，也喜欢运动。","Wǒ xǐhuan yīnyuè, yě xǐhuan yùndòng.","I like music, and sport too.","G39"],["我喜欢苹果、香蕉等水果。","Wǒ xǐhuan píngguǒ, xiāngjiāo děng shuǐguǒ.","I like fruit such as apples and bananas.","G83"],["他喜欢打球、跑步什么的。","Tā xǐhuan dǎ qiú, pǎobù shénme de.","He likes ball games, running and the like.","G91"]],"下":[["在老师的帮助下，我进步很快。","Zài lǎoshī de bāngzhù xià, wǒ jìnbù hěn kuài.","With the teacher's help I improved fast.","G244"],["早不下晚不下，出门就下雨。","Zǎo bù xià wǎn bù xià, chūmén jiù xià yǔ.","It rains the moment I go out, never before or after.","G420"],["我想出去，偏偏下起雨来。","Wǒ xiǎng chūqù, piānpiān xià qǐ yǔ lái.","I wanted to go out and of course it started raining.","G370"]],"下课":[["下课以后我们去打球。","Xiàkè yǐhòu wǒmen qù dǎ qiú.","After class we go play ball.","G95"]],"下雨":[["如果下雨，我们就不去，而是在家看书。","Rúguǒ xià yǔ, wǒmen jiù bù qù, ér shì zàijiā kàn shū.","If it rains we will stay home and read instead.","G343"],["如果天晴就去公园，如果下雨就在家看书。","Rúguǒ tiān qíng jiù qù gōngyuán, rúguǒ xià yǔ jiù zàijiā kàn shū.","If it is fine we go to the park; if it rains we read at home.","G412"],["如果明天下雨，我们就不去了。","Rúguǒ míngtiān xià yǔ, wǒmen jiù bù qù le.","If it rains tomorrow, we won't go.","G114"]],"先":[["什么累不累的，先干完再说。","Shénme lèi bù lèi de, xiān gān wán zàishuō.","Never mind tired — finish it first.","G356"],["先做作业，然后看电视。","Xiān zuò zuòyè, ránhòu kàn diànshì.","First do homework, then watch TV.","G110"],["我先去银行，再去超市。","Wǒ xiān qù yínháng, zài qù chāoshì.","I'll go to the bank first, then the supermarket.","G110"]],"现在":[["要么现在做，要么别做。","Yàome xiànzài zuò, yàome bié zuò.","Either do it now or not at all.","G406"],["现在走还来得及。","Xiànzài zǒu hái láidejí.","There is still time if we leave now.","G237"],["现在是三点半。","Xiànzài shì sān diǎn bàn.","It's half past three.","G7"]],"想":[["因为他病了，所以虽然想来，也没能来。","Yīnwèi tā bìng le, suǒyǐ suīrán xiǎng lái, yě méi néng lái.","Because he was ill, although he wanted to come, he could not.","G343"],["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["他不是不想去，而是没有时间。","Tā bù shì bù xiǎng qù, ér shì méiyǒu shíjiān.","It's not that he doesn't want to go — he has no time.","G254"]],"小":[["放着好好的路不走，偏走小道。","Fàng zhe hǎohǎo de lù bù zǒu, piān zǒu xiǎo dào.","A perfectly good road there, and he takes the back lane.","G422"],["这件衣服不大不小，正合适。","Zhè jiàn yīfu bù dà bù xiǎo, zhèng héshì.","This garment is neither too big nor too small — just right.","G164"],["小王来了。他带来了好消息。","Xiǎo wáng lái le. Tā dàilái le hǎo xiāoxi.","Xiao Wang arrived. He brought good news.","G357"]],"小时":[["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["我等他等了一个小时。","Wǒ děng tā děng le yī gè xiǎoshí.","I waited an hour for him.","G189"],["我等了一个多小时。","Wǒ děng le yī gè duō xiǎoshí.","I waited over an hour.","G121"]],"笑":[["哭也哭不得，笑也笑不得。","Kū yě kū bù dé, xiào yě xiào bù dé.","I could neither cry nor laugh.","G348"],["他不但不生气，反而笑了。","Tā bùdàn bù shēngqì, fǎn'ér xiào le.","Far from being angry, he laughed.","G403"],["他一会儿哭，一会儿笑。","Tā yīhuìr kū, yīhuìr xiào.","He cries one moment and laughs the next.","G191"]],"写":[["请写清楚，以便我们联系你。","Qǐng xiě qīngchu, yǐbiàn wǒmen liánxì nǐ.","Please write clearly so that we can contact you.","G340"],["把地址写下来，好找到你。","Bǎ dìzhǐ xiě xiàlái, hǎo zhǎodào nǐ.","Write the address down so we can find you.","G269"],["他写汉字写得很漂亮。","Tā xiě Hànzì xiě dé hěn piàoliang.","He writes characters beautifully.","G189"]],"新":[["这是我买的那两本新书。","Zhè shì wǒ mǎi de nà liǎng běn xīn shū.","These are the two new books I bought.","G247"],["桌子上的书是新的。","Zhuōzi shàng de shū shì xīn de.","The book on the table is new.","G87"],["这是新买的电脑。","Zhè shì xīn mǎi de diànnǎo.","This is a newly bought computer.","G27"]],"星期":[["今天星期一。","Jīntiān xīngqī yī.","Today is Monday.","G96"]],"行":[["或是坐车，或是走路，都行。","Huòshì zuò chē, huòshì zǒulù, dōu xíng.","By bus or on foot — either is fine.","G331"],["你或者他去都行。","Nǐ huòzhě tā qù dōu xíng.","Either you or he can go — it's fine.","G77"]],"休息":[["既然你不舒服，就早点儿休息吧。","Jìrán nǐ bù shūfu, jiù zǎo diǎn ér xiūxi ba.","Since you are unwell, get some rest.","G266"],["你还是早点儿休息吧。","Nǐ háishi zǎo diǎn ér xiūxi ba.","You'd better get to bed early.","G93"],["周末他往往在家休息。","Zhōumò tā wǎngwǎng zàijiā xiūxi.","At weekends he tends to rest at home.","G145"]],"学":[["拿我来说，我每天都学两个小时。","Ná wǒ lái shuō, wǒ měi tiān dōu xué liǎng gè xiǎoshí.","Take me: I study two hours every day.","G316"],["为了学好汉语，他每天听录音。","Wèile xué hǎo Hànyǔ, tā měi tiān tīng lùyīn.","To master Chinese he listens to recordings daily.","G156"],["自去年以来，他一直在学汉语。","Zì qùnián yǐlái, tā yīzhí zài xué Hànyǔ.","Since last year he has been studying Chinese.","G241"]],"学生":[["三分之二的学生通过了考试。","Sān fēn zhī èr de xuéshēng tōngguò le kǎoshì.","Two-thirds of the students passed.","G273"],["对学生来说，学习最重要。","Duì xuéshēng lái shuō, xuéxí zuì zhòngyào.","For students, study matters most.","G170"],["作为学生，应该好好学习。","Zuòwéi xuéshēng, yīnggāi hǎohǎo xuéxí.","As a student one should study hard.","G229"]],"学习":[["对学生来说，学习最重要。","Duì xuéshēng lái shuō, xuéxí zuì zhòngyào.","For students, study matters most.","G170"],["作为学生，应该好好学习。","Zuòwéi xuéshēng, yīnggāi hǎohǎo xuéxí.","As a student one should study hard.","G229"],["在学习中遇到了一些困难。","Zài xuéxí zhōng yùdào le yīxiē kùnnan.","I ran into some difficulties while studying.","G244"]],"学校":[["我家离学校很近。","Wǒ jiā lí xuéxiào hěn jìn.","My home is close to the school.","G75"],["学校位于市中心。","Xuéxiào wèiyú shì zhōngxīn.","The school is in the city centre.","G371"],["他在学校工作。","Tā zài xuéxiào gōngzuò.","He works at a school.","G16"]],"要":[["一方面要工作，另一方面要照顾家人。","Yīfāngmiàn yào gōngzuò, lìng yīfāngmiàn yào zhàogù jiārén.","On one hand there is work, on the other looking after family.","G192"],["他一时说要去，一时又说不去。","Tā yīshí shuō yào qù, yīshí yòu shuō bù qù.","One minute he says he is going, the next he is not.","G401"],["首先要健康，其次才是成绩。","Shǒuxiān yào jiànkāng, qícì cái shì chéngjì.","Health comes first, marks second.","G256"]],"也":[["因为他病了，所以虽然想来，也没能来。","Yīnwèi tā bìng le, suǒyǐ suīrán xiǎng lái, yě méi néng lái.","Because he was ill, although he wanted to come, he could not.","G343"],["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["这也不行，那也不好，很难办。","Zhè yě bùxíng, nà yě bù hǎo, hěn nán bàn.","This will not do and that is no good — it is hard to please him.","G425"]],"一":[["他东一句西一句，说不到点子上。","Tā dōng yī jù xī yī jù, shuō bù dào diǎnzi shàng.","He rambles without getting to the point.","G394"],["他每天早起，为的是多学一点。","Tā měi tiān zǎo qǐ, wèi de shì duō xué yī diǎn.","He gets up early in order to study more.","G339"],["你一句，我一句，聊得很热闹。","Nǐ yī jù, wǒ yī jù, liáo dé hěn rènao.","A word from you, a word from me — a lively chat.","G393"]],"衣服":[["这件衣服不大不小，正合适。","Zhè jiàn yīfu bù dà bù xiǎo, zhèng héshì.","This garment is neither too big nor too small — just right.","G164"],["穿红衣服的那个人是谁？","Chuān hóng yīfu de nà gèrén shì shéi?","Who is the person in the red clothes?","G175"],["这件衣服有点儿贵。","Zhè jiàn yīfu yǒudiǎnr guì.","This piece of clothing is a bit expensive.","G61"]],"医生":[["他是医生。","Tā shì yīshēng.","He is a doctor.","G36"]],"医院":[["他住了三天医院。","Tā zhù le sān tiān yīyuàn.","He spent three days in hospital.","G396"]],"一会儿":[["天气一会儿冷，一会儿热。","Tiānqì yīhuìr lěng, yīhuìr rè.","The weather is cold one moment and hot the next.","G191"],["他一会儿哭，一会儿笑。","Tā yīhuìr kū, yīhuìr xiào.","He cries one moment and laughs the next.","G191"],["不一会儿他就来了。","Bù yīhuìr tā jiù lái le.","Before long he arrived.","G90"]],"一样":[["我的手机跟你的一样。","Wǒ de shǒujī gēn nǐ de yīyàng.","My phone is the same as yours.","G107"],["他跟我一样高。","Tā gēn wǒ yīyàng gāo.","He is as tall as me.","G107"]],"一边":[["他一边吃饭，一边看电视。","Tā yībiān chīfàn, yībiān kàn diànshì.","He eats while watching TV.","G39"]],"一点儿":[["还朋友呢，一点儿都不帮忙。","Hái péngyou ne, yīdiǎnr dōu bù bāngmáng.","Some friend — no help at all.","G284"],["他一点儿都不在乎。","Tā yīdiǎnr dōu bùzàihu.","He doesn't care in the least.","G205"],["他一点儿都不累。","Tā yīdiǎnr dōu bù lèi.","He is not tired in the slightest.","G171"]],"一起":[["既然你来了，就一起吃饭吧。","Jìrán nǐ lái le, jiù yīqǐ chīfàn ba.","Since you are here, eat with us.","G231"],["一起吃饭，怎么样？","Yīqǐ chīfàn, zěnmeyàng?","How about eating together?","G124"],["我们一起吃饭吧。","Wǒmen yīqǐ chīfàn ba.","Let's eat together.","G10"]],"一些":[["桌上有书、笔以及一些纸。","Zhuō shàng yǒu shū, bǐ yǐjí yīxiē zhǐ.","On the table are books, pens and some paper.","G230"],["在学习中遇到了一些困难。","Zài xuéxí zhōng yùdào le yīxiē kùnnan.","I ran into some difficulties while studying.","G244"]],"有":[["要是有问题就说，否则我就当没事。","Yàoshi yǒu wèntí jiù shuō, fǒuzé wǒ jiù dāng méi shì.","Say so if there is a problem, otherwise I will assume all is well.","G334"],["对于这个问题，我有不同看法。","Duìyú zhè gè wèntí, wǒ yǒu bù tóng kànfǎ.","On this question I take a different view.","G225"],["真有他的，居然想出这个办法。","Zhēn yǒu tā de, jūrán xiǎng chū zhè gè bànfǎ.","Trust him to come up with that.","G354"]],"有的":[["别着急，时间有的是。","Bié zháojí, shíjiān yǒudeshì.","Don't rush — there's plenty of time.","G167"],["这样的机会有的是。","Zhèyàng de jīhuì yǒudeshì.","There is no shortage of such chances.","G167"]],"有用":[["光说不做没有用。","Guāng shuō bù zuò méiyǒu yòng.","Talking without doing is useless.","G143"]],"右":[["他左思右想，还是决定去。","Tā zuǒ sī yòu xiǎng, háishi juédìng qù.","After turning it over and over he decided to go.","G386"],["左看右看都不合适。","Zuǒ kàn yòu kàn dōu bù héshì.","However I look at it, it does not suit.","G386"]],"雨":[["天下起雨来，于是我们回家了。","Tiānxià qǐ yǔ lái, yúshì wǒmen huí jiā le.","It began to rain, so we went home.","G257"],["根据天气预报，明天有雨。","Gēnjù tiānqì yùbào, míngtiān yǒu yǔ.","According to the forecast it will rain tomorrow.","G228"],["我想出去，偏偏下起雨来。","Wǒ xiǎng chūqù, piānpiān xià qǐ yǔ lái.","I wanted to go out and of course it started raining.","G370"]],"元":[["共计三百元。","Gòngjì sān bǎi yuán.","Three hundred yuan altogether.","G217"]],"月":[["依照惯例，会议每月一次。","Yīzhào guànlì, huìyì měi yuè yī cì.","By convention the meeting is monthly.","G301"],["今天是五月八号。","Jīntiān shì wǔ yuè bā hào.","Today is 8 May.","G44"],["明天三月八号。","Míngtiān sān yuè bā hào.","Tomorrow is 8 March.","G102"]],"再":[["关于这件事，我们再讨论。","Guānyú zhè jiàn shì, wǒmen zài tǎolùn.","We'll discuss this matter further.","G226"],["我先去银行，再去超市。","Wǒ xiān qù yínháng, zài qù chāoshì.","I'll go to the bank first, then the supermarket.","G110"],["自那天起，他再没来过。","Zì nà tiān qǐ, tā zài méi lái guò.","From that day on he never came again.","G224"]],"在":[["他不是在教室，就是在图书馆。","Tā bù shì zài jiàoshì, jiùshì zài túshūguǎn.","He is either in the classroom or in the library.","G197"],["自去年以来，他一直在学汉语。","Zì qùnián yǐlái, tā yīzhí zài xué Hànyǔ.","Since last year he has been studying Chinese.","G241"],["在老师的帮助下，我进步很快。","Zài lǎoshī de bāngzhù xià, wǒ jìnbù hěn kuài.","With the teacher's help I improved fast.","G244"]],"在家":[["如果下雨，我们就不去，而是在家看书。","Rúguǒ xià yǔ, wǒmen jiù bù qù, ér shì zàijiā kàn shū.","If it rains we will stay home and read instead.","G343"],["如果天晴就去公园，如果下雨就在家看书。","Rúguǒ tiān qíng jiù qù gōngyuán, rúguǒ xià yǔ jiù zàijiā kàn shū.","If it is fine we go to the park; if it rains we read at home.","G412"],["周末他往往在家休息。","Zhōumò tā wǎngwǎng zàijiā xiūxi.","At weekends he tends to rest at home.","G145"]],"早":[["要是早点出发就好了，否则会迟到。","Yàoshi zǎo diǎn chūfā jiù hǎo le, fǒuzé huì chídào.","Better to set off early, otherwise we will be late.","G334"],["既然你不舒服，就早点儿休息吧。","Jìrán nǐ bù shūfu, jiù zǎo diǎn ér xiūxi ba.","Since you are unwell, get some rest.","G266"],["他每天早起，为的是多学一点。","Tā měi tiān zǎo qǐ, wèi de shì duō xué yī diǎn.","He gets up early in order to study more.","G339"]],"早上":[["我明天早上八点在楼下等你。","Wǒ míngtiān zǎoshang bā diǎn zài lóu xià děng nǐ.","I will wait for you downstairs at eight tomorrow morning.","G320"]],"怎么":[["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["不管天气怎么样，我都去。","Bùguǎn tiānqì zěnmeyàng, wǒ dōu qù.","I am going whatever the weather.","G264"],["这个字我怎么也想不起来。","Zhè gè zì wǒ zěnme yě xiǎng bù qǐlái.","I simply cannot recall this character.","G346"]],"站":[["门口站着两个人。","Ménkǒu zhàn zhe liǎng gèrén.","Two people are standing at the door.","G104"]],"找":[["我找了他两次。","Wǒ zhǎo le tā liǎng cì.","I looked for him twice.","G180"]],"找到":[["他去是去了，不过没找到人。","Tā qù shì qù le, bùguò méi zhǎodào rén.","He did go, but he did not find anyone.","G198"],["把地址写下来，好找到你。","Bǎ dìzhǐ xiě xiàlái, hǎo zhǎodào nǐ.","Write the address down so we can find you.","G269"],["我好不容易才找到你。","Wǒ hǎo bùróng yì cái zhǎodào nǐ.","I had a hard time finding you.","G389"]],"这":[["这也不吃，那也不喝，你想怎么样？","Zhè yě bù chī, nà yě bù hē, nǐ xiǎng zěnmeyàng?","You will not eat this or drink that — what do you want?","G425"],["这不是钱的问题，而是原则问题。","Zhè bù shì qián de wèntí, ér shì yuánzé wèntí.","This is not about money but about principle.","G254"],["对于这个问题，我有不同看法。","Duìyú zhè gè wèntí, wǒ yǒu bù tóng kànfǎ.","On this question I take a different view.","G225"]],"这边":[["请往这边看。","Qǐng wǎng zhèbiān kàn.","Please look this way.","G70"]],"这里":[["这里不光风景好，而且很安静。","Zhèlǐ bùguāng fēngjǐng hǎo, érqiě hěn ānjìng.","The scenery here is lovely, and it is quiet too.","G196"],["这里的菜好吃，而且不贵。","Zhèlǐ de cài hǎochī, érqiě bù guì.","The food here is tasty, and cheap too.","G111"],["他曾经在这里工作过。","Tā céngjīng zài zhèlǐ gōngzuò guò.","He once worked here.","G144"]],"这些":[["这些东西以后用得着。","Zhèxiē dōngxi yǐhòu yòngdezháo.","These things will come in useful later.","G312"],["这些书大都很旧了。","Zhèxiē shū dàdū hěn jiù le.","Most of these books are old.","G291"]],"着":[["放着好好的路不走，偏走小道。","Fàng zhe hǎohǎo de lù bù zǒu, piān zǒu xiǎo dào.","A perfectly good road there, and he takes the back lane.","G422"],["车放着也是放着，你开走吧。","Chē fàng zhe yě shì fàng zhe, nǐ kāi zǒu ba.","The car is just sitting there — take it.","G350"],["闲着也是闲着，帮个忙吧。","Xián zhe yě shì xián zhe, bāng gè máng ba.","You are free anyway — lend a hand.","G350"]],"真":[["真有他的，居然想出这个办法。","Zhēn yǒu tā de, jūrán xiǎng chū zhè gè bànfǎ.","Trust him to come up with that.","G354"],["真有你的，这么快就做完了。","Zhēn yǒu nǐ de, zhème kuài jiù zuò wánle.","Good on you — finished already.","G354"],["不看不知道，一看真不错。","Bù kàn bùzhī dào, yī kàn zhēn bùcuò.","You cannot tell until you look — and it is really rather good.","G417"]],"正":[["这件衣服不大不小，正合适。","Zhè jiàn yīfu bù dà bù xiǎo, zhèng héshì.","This garment is neither too big nor too small — just right.","G164"]],"正在":[["他正在打电话。","Tā zhèngzài dǎ diànhuà.","He is on the phone right now.","G11"],["他正在睡觉呢。","Tā zhèngzài shuìjiào ne.","He is sleeping right now.","G42"]],"知道":[["连他都不知道，我更不清楚。","Lián tā dōu bùzhī dào, wǒ gèng bù qīngchu.","If even he does not know, I certainly do not.","G405"],["很多人，甚至孩子都知道。","Hěn duō rén, shènzhì háizi dōu zhīdào.","Many people, even children, know it.","G258"],["不问不知道，一问吓一跳。","Bù wèn bùzhī dào, yī wèn xià yī tiào.","You would never know until you ask — and then it startles you.","G417"]],"中":[["在学习中遇到了一些困难。","Zài xuéxí zhōng yùdào le yīxiē kùnnan.","I ran into some difficulties while studying.","G244"]],"中国":[["我的中国朋友来了。","Wǒ de Zhōngguó péngyou lái le.","My Chinese friend has arrived.","G87"],["我们都是中国人。","Wǒmen dōu shì Zhōngguó rén.","We are all Chinese.","G10"],["你喜欢中国菜吗？","Nǐ xǐhuan Zhōngguó cài ma?","Do you like Chinese food?","G45"]],"重":[["这就是说，我们得重做。","Zhè jiùshì shuō, wǒmen dé zhòng zuò.","That is to say, we have to redo it.","G391"]],"重要":[["这件事很重要，它关系到大家。","Zhè jiàn shì hěn zhòngyào, tā guānxì dào dàjiā.","This matter is important; it concerns everyone.","G357"],["在他看来，努力比天赋重要。","Zài tā kànlái, nǔlì bǐ tiānfù zhòngyào.","In his view effort matters more than talent.","G318"],["这个问题的重要性不言而喻。","Zhè gè wèntí de zhòngyào xìng bù yán ér yù.","The importance of this question is self-evident.","G360"]],"住":[["他住了三天医院。","Tā zhù le sān tiān yīyuàn.","He spent three days in hospital.","G396"]],"准备":[["他准备得很充分，所以考得很好。","Tā zhǔnbèi dé hěn chōngfèn, suǒyǐ kǎo dé hěn hǎo.","He prepared thoroughly, so he did well in the exam.","G201"],["他准备充分，因而表现出色。","Tā zhǔnbèi chōngfèn, yīn'ér biǎoxiàn chūsè.","He prepared thoroughly and therefore performed excellently.","G337"],["你早点儿说，我好准备。","Nǐ zǎo diǎn ér shuō, wǒ hǎo zhǔnbèi.","Tell me early so I can prepare.","G269"]],"桌子":[["他把杯子放在桌子上。","Tā bǎ bēizi fàng zài zhuōzi shàng.","He put the cup on the table.","G184"],["桌子上摆了一桌子菜。","Zhuōzi shàng bǎi le yī zhuōzi cài.","The table was covered with dishes.","G215"],["桌子上的书是新的。","Zhuōzi shàng de shū shì xīn de.","The book on the table is new.","G87"]],"字":[["这个字我怎么也想不起来。","Zhè gè zì wǒ zěnme yě xiǎng bù qǐlái.","I simply cannot recall this character.","G346"],["墙上写有几个大字。","Qiáng shàng xiě yǒu jǐ gè dà zì.","Several large characters are written on the wall.","G325"],["我一个字也没写。","Wǒ yī gè zì yě méi xiě.","I haven't written a single word.","G171"]],"子":[["他来自一个小村子。","Tā láizì yī gè xiǎo cūn zi.","He comes from a small village.","G224"]],"走":[["当我到家的时候，他已经走了。","Dāng wǒ dào jiā de shíhou, tā yǐjīng zǒu le.","When I got home, he had already left.","G69"],["放着好好的路不走，偏走小道。","Fàng zhe hǎohǎo de lù bù zǒu, piān zǒu xiǎo dào.","A perfectly good road there, and he takes the back lane.","G422"],["车放着也是放着，你开走吧。","Chē fàng zhe yě shì fàng zhe, nǐ kāi zǒu ba.","The car is just sitting there — take it.","G350"]],"走路":[["或是坐车，或是走路，都行。","Huòshì zuò chē, huòshì zǒulù, dōu xíng.","By bus or on foot — either is fine.","G331"],["我们坐车还是走路？","Wǒmen zuò chē háishi zǒulù?","Shall we take a bus or walk?","G112"]],"最":[["对学生来说，学习最重要。","Duì xuéshēng lái shuō, xuéxí zuì zhòngyào.","For students, study matters most.","G170"],["身体健康最重要。","Shēntǐ jiànkāng zuì zhòngyào.","Being healthy matters most.","G245"]],"最好":[["想来想去，就是这个办法最好。","Xiǎng lái xiǎng qù, jiùshì zhè gè bànfǎ zuìhǎo.","After all that thinking, this is still the best way.","G423"]],"昨天":[["他昨天在图书馆认真地看书。","Tā zuótiān zài túshūguǎn rènzhēn de kàn shū.","He read attentively in the library yesterday.","G320"],["他昨天帮了我的忙。","Tā zuótiān bāng le wǒ de máng.","He helped me yesterday.","G135"],["这是我昨天买的书。","Zhè shì wǒ zuótiān mǎi de shū.","This is the book I bought yesterday.","G175"]],"左":[["他左思右想，还是决定去。","Tā zuǒ sī yòu xiǎng, háishi juédìng qù.","After turning it over and over he decided to go.","G386"],["左看右看都不合适。","Zuǒ kàn yòu kàn dōu bù héshì.","However I look at it, it does not suit.","G386"]],"坐":[["或是坐车，或是走路，都行。","Huòshì zuò chē, huòshì zǒulù, dōu xíng.","By bus or on foot — either is fine.","G331"],["我坐公共汽车去上班。","Wǒ zuò gōnggòng qìchē qù shàngbān.","I take the bus to work.","G186"],["我们坐车还是走路？","Wǒmen zuò chē háishi zǒulù?","Shall we take a bus or walk?","G112"]],"做":[["这样做一方面省时间，另一方面省钱。","Zhèyàng zuò yīfāngmiàn shěng shíjiān, lìng yīfāngmiàn shěngqián.","Doing it this way saves both time and money.","G192"],["拿这件事来说，他做得很好。","Ná zhè jiàn shì lái shuō, tā zuò dé hěn hǎo.","Take this matter — he handled it well.","G316"],["真有你的，这么快就做完了。","Zhēn yǒu nǐ de, zhème kuài jiù zuò wánle.","Good on you — finished already.","G354"]]})
